(window.STORIES=window.STORIES||[]).push(...[{"n": 157, "l": "الجزء 131 | احداث السنه السابعه من الهجرة | رسائل رسول الله الي الملوك الجزء الأول", "u": "https://www.facebook.com/groups/710210019782034/permalink/830858334383868/", "t": "افتكرت  درس  السيره لما الاستاذ كان بيحفظنا رسالة الرسول للملوك دي انا كدا فهمت الرساله دي كانت ليه\n \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#رسائل_رسول_الله_إلى_الملوك_الجزء_الأول\nكنا قلنا إن بعد صلح الحديبية إللي ربنا سمّاه فتح هتبدأ مرحلة جديدة من الدعوة إلى الإسلام وهي عالمية الدعوة،\nيعني رسول الله ﷺ هيبدأ يخرج بدعوة الإسلام من جزيرة العرب إلى باقي الأرض، فالدعوة هتبقى عالمية،\nلأن رسول الله ﷺ أُرسل إلى الثّقلين الإنس والجن، فالدعوة لازم توصل لكل أهل الأرض،\nوربنا قال:\n\"وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ\"\nوزي ما قيل : الناس على دين ملوكهم، \nيعني على حسب اهتمامات الحاكم الناس هتتبعه في الاهتمامات دي، \nفرسول الله ﷺ قرر إنه يرسل رسائل لرؤساء وزعماء وملوك الأرض:\n《كِسْرَى وقَيْصَر والنّجاشي والمُقَوْقِس》وغيرهم يدعوهم فيها للإسلام،\n☆ممكن حد يسأل:\nطيب ليه رسول الله ﷺ لم يُرسل لملوك الأرض من أول يوم في الدعوة مادام هو كده كده هيدعوهم\nلسبب بسيط جدا وهو إن رسول الله ﷺ واقعي\nتخيلوا كده معايا واحد طالع في قرية صغيرة غير معروفة أصلا بيطلب من كل زعماء العالم إنهم يتبعوه ويغيّروا دينهم لدين محدش سمع بيه قبل كده،\nولو سمعوا، هيسمعوا إيه؟\nهيسمعوا عن التشريد والاضطهاد والتعذيب لأتباع الدين ده،\nفمين بقى إللي هياخد خطوة كبيرة جدا زي دي ويبدل عقيدته عشان مجموعة من الضعفاء في قرية صغيرة من قُرى العالم\nوهتشوفوا موقف كسرى ملك الفرس بعد شوية هيبقى عامل إزاي،\nفرسول الله ﷺ بيعلمنا واقعية المنهج، يعني بعد ما ثَبّت أقدامه وبقى له دولة وبقى في معاهدة صُلح مع قريش العدو الأول للإسلام كده بقى في اعتراف رسمي بدولة المسلمين، فهنا بقى يقدر رسول الله ﷺ ياخد خطوة جديدة في الدعوة للإسلام\nوكمان نقطة مهمة، لو رسول الله ﷺ أرسل رسائل لملوك الأرض كان ممكن يلفت الانتباه له وللمجموعة الصغيرة إللي معاه فيُبادوا كلهم وتضيع رسالة الإسلام،\nومحدش يقول إن ممكن ربنا سبحانه وتعالى يفتح قلوب الزعماء ويضحوا بملكهم وسلطانهم عشان خاطر دعوة الإسلام\nهو فعلا ربنا قادر على كده وده رسوله ﷺ لكن زي ما قلنا قبل كده رسول الله ﷺ قدوة واحنا بنتعلم منه، فلازم ياخد بالأسباب المنطقية في الدعوة عشان يعلم كل الأجيال إللي هتيجي بعده،\nربنا بيفتح قلوب العباد للداعي لما هو يبذل الأسباب الصحيحة إللي يقدر عليها الأول، وهو ده إللي رسول الله ﷺ عمله،\nفعشان دعوته تكون على الأقل مقبولة والناس تبدأ تسمع لها كان لازم يحل مشكلته مع قريش؛ لأنه في نظر الناس هو وإللي معاه مجرد جماعة غير شرعية خرجت عن منهج الدولة الأم إللي هي قريش،\nوقريش القبيلة العربية العزيزة كانت معروفة لكل الناس حتى خارج الجزيرة العربية، \nوكان لها علاقات اقتصادية وسياسية مع معظم القوى الموجودة في العالم ساعتها حتى لو مكنتش في قوة فارس والروم، لكنها معروفة ومُعترف بيها،\nفلما قريش تعمل معاهدة مع رسول الله ﷺ وإللي معاه؛ ده اعتراف منهم إن رسول الله ﷺ وأتباعه مش مجرد مجموعة متمردة، لأ، دول ناس لهم دولة وكيان مُعترف بيهم،\nوده هيخلي الزعماء يستقبلوا فكرة المراسلة بينهم وبين رسول الله ﷺ ويبدأوا يفكروا: \nهل الدين الجديد دين ده يستحق الاتباع، ولّا صاحبه بيكذب علينا، ويبدأوا يدوّروا على حقيقة الإسلام زي ما هرقل ملك الروم عمل وهنشوف موقفه كان إيه بعدين،\nومتنسوش إن كل ما كان المُرسِل قوي كل ما الناس أخذت كلامه بجدية\nبدأ رسول الله ﷺ في إرسال الرسائل أواخر السنة السادسة من الهجرة بعد ما رجع للمدينة على طول بعد صلح الحديبية، واستمر لحد أوائل السنة السابعة من الهجرة، \nرسول الله ﷺ أرسل سفراء معاهم رسائل منه يدعو فيها ملوك وزعماء سبعة للإسلام هم:\n◇كسرى ملك الفرس\n◇المُنذر بن سَاوى ملك البحرين\n◇المُقَوقِس ملك مصر\n◇هَوْذَة بن علي حاكم اليمامة\n◇الحارث بن أبي شَمِر أو شُمّر الغَسّاني\n◇النجاشي ملك الحبشة\n◇هِرَقْل ملك الروم\nرسول الله ﷺ هيرسل سفراء تانيين لحكام بلاد تانية في السنة الثامنة والتاسعة للهجرة بعد ما هيكون الإسلام انتشر وأعداد المسلمين بقت كبيرة ومعظهم هيدخلوا في الإسلام،\nلكن السبع ملوك إللي قلنا عليهم دول\n هم كانوا أول ناس تعرف عن الإسلام من خارج الجزيرة العربية،\nواحنا لازم نفهم إننا كمسلمين علينا دور توصيل الإسلام إلى كل مكان في العالم، \nوده مش تفَضّل مننا، ده واجب علينا،\nوالكلام ده الصحابة فهموه كويس عشان كده حتى بعد وفاة رسول الله ﷺ خرجوا لنشر الإسلام في كل مكان\nمضمون رسالة رسول الله ﷺ للسبعة تقريبا واحد، يعني مفيش اختلاف كبير بين الرسائل؛ لأن هو بيدعوهم إلى الإسلام واتّباعه ﷺ ودعوة الإسلام واحدة لكل الناس حاكم أو محكوم،\nلكن الموضوع مش سهل\nلأن الملك سيتحول من ملك مُطاع لا تُرد له كلمة إلى تابع مُطيع يَرُد الأمر كله لله عز وجل ولرسوله ﷺ، \nواحنا نقدر نتوقع رد الفعل إللي هيحصل من الملوك دول\nكل واحد منهم كان له قصة مع رسالة رسول الله ﷺ، \nفاحنا هنشوف رسالة رسول الله ﷺ لكل واحد من الملوك دول كانت بتقول إيه ونشوف موقف كل واحد منهم من رسالته ﷺ \n☆ملحوظة:\nطبعا الملوك دول مش عايشين في الشارع إللي وراء المدينة، ولا السفراء هيروحوا لهم بالطيارة مثلا\nده سفر طويل، يعني عشان مثلا الصحابي يروح لواحد منهم محتاج له شهر رايح وشهر راجع\nفرسول الله ﷺ خلال كم يوم وجّه سبعة من الصحابة للسبع ملوك والزعماء دول وهو بقى كمل مسؤولياته عادي جدا مقعدش مستني النتيجة بقى هتبقى إيه،\nيعني بعد ما كتب لهم الرسائل وأخذها الصحابة وانطلقوا بيها، رسول الله ﷺ خرج للجهاد بعدهم على طول في شهر محرم وتوجه لغزو خيبر،\nففي نفس الوقت إللي كان رسائل الملوك في الطريق لهم كان رسول الله ﷺ خارج بجيش للجهاد،\nعشان بس نربط بين الأحداث\nفالأول هنتكلم عن الرسائل وردود فعل أصحابها وبعدين نرجع نشوف أحداث غزوة خيبر وإزاي حصلت في شهر الله المحرم\nنشوف أول واحد من الملوك:\n◇كسرى ملك الفرس:\nأرسل رسول الله ﷺ لكسرى الصحابي\n 《عبد الله بن حُذافة السّهْمِي》 برسالة يقول له فيها:\n\"بسم الله الرحمن الرحيم \nمن محمد رسول الله إلى كسرى عظيم فارس، سلام على من اتبع الهدى وآمن بالله ورسوله، وأشهد أنه لا إله إلا الله وحده لا شريك له، وأن محمداً عبده ورسوله، \nأدعوك بدعاية الله، فإني رسول الله إلى الناس كافة، ليُنذر من كان حيّا ويَحق القول على الكافرين، فأسْلِم تَسْلَم، فإن أَبيْت فإن إثم المجُوسِ عليكَ\"\n☆الفرس كانوا يعبدون النار .\nرسائل رسول الله ﷺ للملوك كانت تتميز بالوضوح والقوة والعزة والحكمة في كل كلمة،\nوكان ﷺ حريص على ظهور عزته وعزة الدولة الإسلامية في كل كلمة من كلمات الرسالة،\nخلونا نحلل رسالته كده:\n◇أولاً: \nبدأ رسول الله ﷺ باسمه قبل اسم كسرى ، والكلام ده خطير جداً في زمانهم، وبعدين دعاه مباشرة إلى الدخول في الإسلام، فقال: (أسلم تسلم) بصيغة الأمر،\nمش إنه عرض الموضوع بصيغة فيها تردد ويعطي المجال للرفض أو القبول،\nيعني ده الطريق الوحيد إللي قصادك عشان تَسلم في الدنيا والآخرة وده كان ترغيب لكسرى.\n◇ثانيا:\nفي نفس الوقت إللي رسول الله ﷺ كان بيُظهر عزة الإسلام وبيتكلم بقوة إلا إنه لم يُقلل من قيمة الطرف التاني إللي بيكلمه، بالعكس ده رفع قدره وحفظ مكانته،\nوقال : كسرى عظيم فارس وحيّاه بقوله :\nسلام على من اتبع الهدى، فعلى الرغم من إنه كافر إلا إنه بدأ معاه بتحية،\n☆وهنا في معلومة بما إننا بنتكلم عن المكانة\nفي حديث عن رسول الله ﷺ قال: \"أنِزلُوا الناس منازلهم\"\nيعني كل واحد أعطوه منزلته واحفظوا له مكانته، الحديث وإن كان معناه صحيح فهو فيه ضعف، بعض العلماء صحّحُوه، لكن الأغلب قالوا ضعيف، عشان لو قرأتم الحديث في أي مكان تبقوا عارفين أصله إيه\nبدأ يبيّن رسول الله ﷺ عظمة الإسلام وأن الأمن والسلام على مَن آمن بالله ورسوله وشهد أن لا إله إلا الله وحده لا شريك له، وأن محمدا عبده ورسوله بكلام مختصر بليغ،\nجمع بين الترغيب والترهيب،\nفرهّبه بإنه لو لم يُسلم هيكون عليه وزر شعبه، وهو إللي هيتحمل أوزارهم لأنه لما يترك الإسلام شعبه هيتركه؛\nولأنه حجب عنهم دعوة الإسلام\nالكلام عادي وبسيط جدا وسهل أهه\n◇رد فعل كسرى كان إيه بقى\nأول ما سمع الرسالة من المترجم إللي كان بيترجم من العربية للفارسية غضب كسرى جدا وراح واخد رسالة رسول الله ﷺ ومقطعها\nحتى يُقال في بعض الروايات إنه مكملش سماع رسالة رسول الله ﷺ ومجرد ما لقى إن رسول الله ﷺ مُقدّم اسمه على اسم كسرى راح واخد الرسالة ومقطعها،\nولعل هزيمة كسرى الأخيرة على أيدي الروم كانت من أسباب شدة انفعاله؛ لأنه ظن أن الأعراب والتابعين بدأوا يتجرأوا عليه،\nوهنعرف إيه قصة هزيمة الفرس واحنا بنتكلم عن هرقل إن شاء الله\nالمهم يعني إن كسرى قطع رسالة رسول الله ﷺ، \nوقال بكل غضب وتكبر:\nعبدٌ من رعيتي يكتب اسمه قبلي\nهو اتعامل مع رسالة رسول الله ﷺ بكل سطحية ومبصش على مضمون الرسالة ولا المعاني المهمة إللي في الرسالة.\n☆موقف كسرى ده بيفكرني بالناس إللي الواحد بينصحهم وبيدلهم على الخير وبيختار الكلام المناسب وبعدين يسيبوا كل المعاني المهمة في الكلام ويقولوا إيه الأسلوب إللي بتتكلموا بيه ده، أسلوبكم وحش\nومش حافظين غير ولو كنت فظا غليظ القلب لانفضوا من حولك، وهم أصلا فاهمين معناها غلط، وبيتركوا اتباع الحق بحجة سوء الأسلوب،\nوناسيين إن إللي قال ولو كنت فظا غليظ القلب لانفضوا من حولك هو نفسه إللي قال:\n\"الَّذِينَ يَسْتَمِعُونَ الْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُ ۚ أُولَٰئِكَ الَّذِينَ هَدَاهُمُ اللَّهُ ۖ وَأُولَٰئِكَ هُمْ أُولُو الْأَلْبَابِ\" \nوهو إللي قال:\n\"وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ أَخَذَتْهُ الْعِزَّةُ بِالإِثْمِ\"\nفالناس دي للأسف بتاخد من الدين إللي يوافق هواها\nربنا لا يجعلنا وإياكم منهم\nفكسرى شاف إن إزاي واحد من رعايا رعاياه يقدم اسمه على اسمه،\nورعايا كسرى هم الغَسَاسنة والمَنَاذِرة كانوا بيحكموا مناطق معينة في الجزيرة العربية ،\nفكانوا زي الخدم لكِسرى، ورعايا كسرى من الغَسَاسنة والمَنَاذِرة كانوا بالنسبة للعرب ملوك،\nفتخيلوا وضع العرب كان عامل إزاي قبل الإسلام، وزي ما قال عمر رضي الله عنه:\n\"إنَّا كنَّا أذلَّ قوم، فأعزَّنا الله بالإسلام\"\nفرسول الله ﷺ سيد ولد آدم من وجهة نظر كسرى هو خادم لخدّامه، متخيلين نظرة الفرس للعرب كانت إيه\nولحد دلوقتي لسه نظرة الاحتقار والكبر على العرب موجودة عند الفرس\nوكسرى مسكتش لحد كده، ده عايز يعتقل رسول الله ﷺ ويجيبه عنده عشان يعاقبه بنفسه، \nفأرسل 《لبَاذان》أو باذام عامله على اليمن وهو فارسي، لأن اليمن كانت قريبة من المدينة، واحنا كنا حكينا قبل كده إزاي اليمن بقت تحت حكم الفرس بعد مقتل أبرهة،\nفكسرى بيقول لباذان ابعت رجلين من عندك يجيبوا لي الرجل إللي بيقول على نفسه نبي ده وهاتهولي القصر بتاعي في المدائن،\nشوفوا نظرته للعرب كانت إيه\nمقلوش ابعت جيش ولا هو أمر بإرسال جيش، ده بيقول له رجلين بس كفاية إنهم يجيبوا رسول الله ﷺ، وقال له خليهم يهددوه إنه لو مسمعش الكلام هيقتلوه، \nفراح رسول كسرى إلى باذان في اليمن عشان يبلغه برسالة كسرى،\nفي نفس الوقت كان عبد الله بن حذافة السهمي رجع لرسول الله ﷺ وأخبره إن كسرى لما سمع رسالته مزّقها، قطعها يعني، فقال رسول الله ﷺ:\nمزّق الله مُلكَه\nوصل رسول كسرى لباذان فأمر رجلين إنهم يروحوا يقبضوا على رسول الله ﷺ، \nوصل الرجلان لرسول الله ﷺ فلما شافهم رسول الله ﷺ وكانوا حالقين لحاهم وتاركين شاربهم كره منظرهم وسألهم رسول الله ﷺ مين أمركم بكده، فقالا له أمرنا ربنا كسرى،\nفقال لهم رسول الله ﷺ:\n\" لَكِنَّا نُخَالِفُ سُنَّتَكُمْ ، نَجُزُّ هَذَا وَنُرْسِلُ هَذَا\"\nيعني نَحُفّ الشارب ونُعفي اللّحية، واتكلمنا قبل كده عن موضوع اللحية بالتفصيل فمش هعيد\nالمهم قالوا لرسول الله ﷺ يا إما تقعد في بيتك وتسيبك من الكلام إللي انت بتدعوا الناس ليه ده، \nأو هناخدك معانا لكسرى يتصرف معاك، فقال لهم سول الله ﷺ إنه هيرد عليهم بكرة،\nفلما جاءاه قال لهما:\nارجعوا لصاحبكم وقولا له إن ربي قتل ربكما الليلة، \nيعني مش هتشوفوا كسرى مرة تانية؛\nلأن ربنا قتله، فهو سلَّط عليه ابنه شِيروِيه وقتَله\nطبعا رسول الله ﷺ عرف عن طريق الوحي\nفالرجلين نظرا لرسول الله ﷺ وهم مدهوشين إزاي عرف المعلومة دي والخبر بييجي من فارس لجزيرة العرب في شهر وقالا له:\nنقول كده لباذان\nفقال لهما : نعم، وقولا له : إن ديني سيبلغ ما وصل إليه ملك كسرى ، وإنَّك إن أسلمتَ ، أعطيتكَ ما تحت يديك ، وملَّكتكَ على قومك.\nيعني رسول الله ﷺ بيقول مُلك المسلمين هيبلغ ملك كسرى، وإنه لو أسلم هيخليه هو الحاكم ويكون تابع لدولة الإسلام،\nفرجع الرجلان لباذان وحكوا له القصة وإن كسرى قتل في ليلة كذا على يد ابنه،\nفقال باذان وكان رجل عاقل حكيم، إن كلام رسول الله ﷺ مش كلام مَلك ده كلام نبي وفعلا كلامه هيتحقق، ولو هو بيكذب خلينا نستنى الخبر لما ييجي من الفرس ونتأكد،\nبعد شهر وصل لهم الخبر إن فعلا كسرى قُتل وإللي قتله ابنه بعد ما ثار عليه في نفس الليلة إللي رسول الله ﷺ قال عليها،\nودي كانت أول بداية لاستجابة دعوة رسول الله ﷺ على كسرى: 《مزق الله ملكه》\nوتمت الدعوة لما تم فتح فارس في عهد عمر بن الخطاب رضي الله عنه،\nفلما شاف باذان صدق رسول الله ﷺ دخل في الإسلام\nوأسلم أبناؤه وأسلم كل الفرس إللي كانوا معاه تقريبا وأسلم الرجلان إللي جاءا لرسول الله ﷺ، وبدأ يسلم معاه أهل اليمن،\nووصل الخبر لرسول الله ﷺ وفرح بإسلامهم وأقر باذان على حكم اليمن حتى مات،\nشوفوا سبحان الله ربنا استعمل كسرى إزاي عشان يهدي ناس تانية للإسلام\n☆وهنا في فائدة وحكمة جميلة\nوهي إن مجهود الداعية مش بيضيع، مجهوده موجود وهينتشر، لكن مش لازم ينتشر في الاتجاه إللي كان مخطط له، \nيعني رسول الله ﷺ لما أرسل رسالته إلى كِسرى كان عايز إسلام شعب فارس إللي موجود في الشمال الشرقي من المدينة،\nلكن تقدير ربنا وإرادته إن شعب اليمن إللي موجود في جنوب المدينة وبعيد جداً عن منطقة فارس هو إللي يدخل في الإسلام،\nفالداعي إلى الله يبذل مجهوده ووِسعُه وهو عارف ومتيقن إنه جهده ده مش هيضيع،\nوممكن كمان ربنا يجعل عدوّه أداة لتوصيل رسالته،\nهو مش كِسرى كان عايز يحارب الإسلام ويقضي عليه، أهه ربنا بقى خلاه أداة لنشر الدين\nوصدق رسول الله ﷺ لما قال:\n\" إن الله ليؤُيّد هذا الدين بالرجل الفاجر\"\nوالرجل الفاجر يشمل مَن كان كافرا ومَن كان فاسقاً، ومش بس كده ده مقدرش حتى يمس رسول الله ﷺ بسوء وهو إللي قُتل وعلى يد ابنه،\n وبكده تجمدت العلاقات بين دولة فارس وبين الدولة الإسلامية، لأن ابن كسرى شيرويه مفكرش في الإسلام أصلا ولاكان مهتم بيه،\nطبعا الأحداث دي حصلت في شهور ومتزامنة مع أحداث تانية لكن حبيت أكمل القصة للآخر عشان تكون مترابطة ومفهومة\nالملك الثاني إللي أرسل له رسول الله ﷺ رسالة هو:\n◇ملك البحرين : المُنذر بن ساوَى وكان هو وقومه يعبدون الأصنام،\nأرسل له رسول الله ﷺ رسالة مع الصحابي\n 《العلاء بن الحَضْرَمي》ومحتوى الرسالة كان قريب من نفس الرسالة إللي أرسلها رسول الله ﷺ لكسرى مع بعض الإختلافات في الألفاظ،\nلكن النتيجة كانت مختلفة تماما، المنذر بن ساوى أسلم وأسلم معه معظم شعبه، وحصل بينه وبين رسول الله ﷺ مراسلات إزاي يتعامل مع اليهود والمجوس إللي كانوا عايشين على أرضه،\nوده دليل واضح أهه إن المشكلة مش في الداعية، ولا في كلامه المشكلة في الشخص إللي بيتلقى الكلام، لو هو بيبحث عن الحق هيقبل الكلام بأي أسلوب،\nلكن لو كان مُتبع لهواه مش هيقبل الحق حتى لو كان الداعية ده رسول الله ﷺ \nإن شاء الله المرة الجاية هنشوف رد فعل باقي الملوك على رسائل رسول الله ﷺ"}, {"n": 158, "l": "الجزء 132 | احداث السنه السابعه من الهجرة | رسائل رسول الله الي الملوك الجزء الثاني | اسلام عمر بن العاص", "u": "https://www.facebook.com/groups/710210019782034/permalink/831618520974516/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#رسائل_رسول_الله_إلى_الملوك_الجزء_الثاني\n#إسلام_عمرو_بن_العاص\n♡الجزء النهاردة طويل شوية عشان نعوض إللي فات\nاتكلمنا الجزء إللي فات عن إرسال رسول الله ﷺ رسائل لملوك وأمراء الأرض يدعوهم فيها للإسلام،\nشوفنا رسالته ﷺ لكسرى وللمنذر بن ساوى ورد فعل كل واحد منهم كان إيه،\nهنكمل باقي رسائل رسول الله ﷺ للخمسة الباقيين،\nالملك الثالث كان:\n◇المُقَوقِس ملك مصر\nوالمقوقس ده لقب مش اسم، فكل ملوك مصر كان لقبهم المقوقس، زي كسرى كده، كل ملوك فارس لقبهم كسرى، وكل ملوك الروم لقبهم هِرقل وكل ملوك الحبشة لقبهم النجاشي،\nالمهم، \nرسول الله ﷺ أرسل له رسالة مع الصحابي حاطِب بن أبي بَلتَعة وكان من الصحابة إللي شهدوا غزوة بدر،\nقال رسول الله ﷺ في رسالته للمقوقس:\n\" بسم الله الرحمن الرحيم\n من محمد عبد الله ورسوله، إلى المقوقس عظيم القبط، سلام على من اتبع الهدى، أما بعد:\n فإني أدعوك بدعاية الإسلام، أسلم تسلم، وأسلم يُؤتك الله أجرك مرتين، فإن تولّيت، فإن عليك إثم القِبْط،\n يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ اللَّهِ ۚ فَإِن تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ \"\nنفس الرسالة إللي أرسلها رسول الله لكسرى مع اختلاف في الألفاظ، وهو لو أسلم هياخد أجرين أجر نفسه وأجر إللي هيتبعه من القبط، وده معنى يُؤتك الله أجرك مرتين،\nحاطب بن أبي بلتعة بدأ يكلم المقوقس ويدعوه للإسلام، قال له:\nكان في واحد قبلك بيقول عن نفسه إن هو الرب الأعلى، \n \"فَأَخَذَهُ اللَّهُ نَكَالَ الْآخِرَةِ وَالْأُولَىٰ\"\nيعني ربنا انتقم منه وجعله عبرة لأمثاله من المتمردين في الدنيا، فاعتبر بغيرك ومتكنش انت عبرة لغيرك\nفالمقوقس قال له:\n\" إن لنا دينا لن ندعه إلا لما هو خير منه\"\nيعني احنا عندنا دين، ومش هنسيب ديننا ده إلا لو في دين أحسن منه،\nفقال له حاطب إن الإسلام مش بينهاك عن دين المسيح، ده  بيأمرك بيه؛ لأن عيسى عليه السلام بشّر بمجيء رسول بعده وهو محمد ﷺ،\nفاتباع محمد ﷺ هو ما أمر به عيسى عليه السلام،\nفبعد حوار بين حاطب والمقوقس، قال المقوقس لحاطب إن الدين ده مش وحش ومفهوش كذب والرسول مش كاذب، \nلكن أنا هبقى أشوف حالي\nيعني تقدروا تقولوا إنه بيرفض بصنعة لطافة، وهو عارف إن رسول الله ﷺ مش كاذب وإنه فعلا رسول من عند الله،\nوأخذ رسالة رسول الله ﷺ فجعلها في حُقٍّ من عاج، \nوختم عليه، ودفعه إلى جارية له، \nيعني هو أكرم رسالة رسول الله ﷺ ووضعها في حاجة زي الفاظة كده وعانها كأنها تحفة،\nمعملش زي كسرى إللي مزق رسالة رسول الله ﷺ،\nفده يُثبت إنه مصدق إن رسول الله ﷺ فعلا رسول من عند الله، وإلا إيه إللي يخليه يحتفظ برسالة واحد هو شايفه كذاب\nوالسبب إللي منعه إنه يدخل في الإسلام هو إنه خاف على ملكه يضيع منه لو دخل في الإسلام،\nيعني هو دلوقتي حاكم لدولة كبيرة وكل البلد والحاشية على النصرانية لو هو دخل في الإسلام طبعا من وجهة نظره إن الناس هتثور عليه ومش هترضى بيه كحاكم وهيشيلوه من الملك،\nفهو أكرم رسالة رسول الله ﷺ وأكرم رسول رسول الله ﷺ حاطب بن أبي بلتعة حامل الرسالة وجهز هدايا لرسول الله ﷺ وأعطاها لحاطب بن أبي بلتعة يعطيها له مع رسالة لرسول الله ﷺ بيقول له فيها:\n\"بسم الله الرحمن الرحيم،\n لمحمد بن عبد الله، من المقوقس عظيم القبط، سلام عليك، أما بعد:\n فقد قرأت كتابك، وفهمت ما ذكرت فيه، وما تدعو إليه، وقد علمتُ أن نبيا بقي، \nوكنت أظن أنه يخرج بالشام، وقد أكرمتُ رسولك، وبعثت لك بجاريتين لهما مكان في القبط عظيم، وبكسوة، وأهديت إليك بغلة لتركبها، والسلام عليك\"\nالمقوقس كان على النصرانية والنصارى عارفين إن في نبي في آخر الزمان هيخرج وكانوا متعودين إن الأنبياء بيخرجوا من الشام من نسل يعقوب عليه السلام إللي هم أنبياء بني إسرائيل،\nفالمقوقس كان مستغرب إن نبي آخر الزمان خرج من الجزيرة العربية مش من الشام كالعادة،\nوالهدايا كانت جاريتين من القبط هما مارية وأختها سِيرين وكانت لهما مكانة عظيمة عند القبط،\nوأهدى له كسوة وبغلة يركبها اسمها دَلْدَل، ولما وصل حاطب بن أبي بلتعة إلى المدينة وسلم رسول الله ﷺ رسالة المقوقس وعرف ما فيها قال:\n\"ضَنّ الخبيثُ بِملكهِ ولا بقاءَ لمُلكه\"\nيعني هو خاف على ملكه من الزوال وملكه أصلا مش هيبقى وهيزول\nبالنسبة للجاريتين مارية وسيرين، فمارية أخذها رسول الله ﷺ ملك يمين، وأهدى أختها سيرين إلى حسان بن ثابت،\nفي روايتين في إسلام مارية القبطية، \n◇الأولى:\nإنها أسلمت في الطريق قبل ما تأتي المدينة لما دعاها حاطب بن أبي بلتعة للإسلام ورغبها فيه هي وأختها سيرين، وكان معهما أخوهما واستمر على دينه وأسلم بعدين في المدينة.\n◇والرواية الثانية إنها لما وصلت للمدينة أنزلها رسول الله ﷺ هي وأختها سيرين في منزل أم سُلَيْم ودعاهما إلى الإسلام فأسلمتا وأخذها رسول الله ﷺ ملك يمين فحملت وولدت له ابنه إبراهيم في السنة الثامنة من الهجرة،\nالشاهد من الكلام إن مارية القبطية أسلمت وأخذها رسول الله ﷺ ملك يمين 《ولم يتزوجها》.\n☆والنقطة دي مهمة؛ لأن زوجات رسول الله ﷺ هم فقط إللي أمهات المؤمنين،\nأما مِلك يمينه ﷺ مش أمهات للمؤمنين، يعني مارية القبطية رضي الله عنها ليست من أمهات المؤمنين\nورسول الله ﷺ كان له أربع نساء ملك يمين غير زوجاته الإحدى عشر،\nمارية القبطية كانت واحدة منهن وأول ملك يمين له كانت ريحانة بنت زيد واتكلمنا عنها في الجزء المائة،\nأما الإثنين الباقيين فواحدة منهم أصابها رسول الله ﷺ في بعض السبي والثانية أهدتها له زوجته زينب بنت جحش رضي الله عنها.\nالملك الرابع إللي رسول الله ﷺ أرسل له رسالة هو :\n◇هَوْذَة بن علي حاكم اليمامة،\nرسول الله ﷺ أرسل له رسالة مع واحد من الصحابة اسمه:\nسَلِيط بن عمرو، الرسالة كان مكتوب فيها:\nبسم الله الرحمن الرحيم؛\"\n من محمد رسول الله إلى هوذة بن علي، سلام على من اتبع الهدى، واعلم أن ديني سيظهر إلى منتهى الخُفّ والحافر أسلم تسلم وأجعل لك ما تحت يديك‏\"\nيعني رسول الله ﷺ بيقول له إن الإسلام هينتشر في كل مكان، فالأحسن لك إنك تدخل في الإسلام ولو دخلت في الإسلام هتفضل الحاكم ومحدش هياخد ملكك منك،\nفلما سمع هوذة رسالة رسول الله ﷺ حس بقوة رسول الله ﷺ وتنبأ لدولة رسول الله ﷺ بمستقبل كبير وإن الدولة دي هتملك العالم،\nفأكرم هوذة رسول رسول الله ﷺ سليط بن عمرو وأعطاه جائزة وكساه أثواب فخمة وأرسل معاه رسالة لرسول الله ﷺ بيقول له فيها:\n\"ما أحسن ما تدعو إليه وأجمله، وأنا شاعر قومي وخطيبهم والعرب تهاب مكاني فاجعل إلى بعض الأمر أَتْبَعُك‏.\"\nواخدين بالكم،\nهوذة مكنش بيفكر في الإسلام كدين وإن هو ده إللي هينجيه في الدنيا والآخرة، ده كان بيدور على الملك\nهو شاف قوة الإسلام وإنه هينتشر فقرر إنه يتفاوض مع رسول الله ﷺ أو بعبارة أدق قرر إنه يُساوِم رسول الله ﷺ، يعني جعل إسلامه في مقابل إنه يكون هو الخليفة بعد رسول الله ﷺ،\nمع إن رسول الله ﷺ وعده إنه مش هياخد منه ملكه، لكن هو كان طماع وعايز مُلك أكبر وعلق إسلامه على الشرط ده،\nطبعا واضح إن واحد زي ده مش هيفيد لا الإسلام ولا المسلمين بالعكس ده هيضرهم؛\nلأنه مفتون بالإِمارة والحكم وهيضحي عشانها بأي حاجة تقف في طريقه، ولو تعارض الإسلام مع الإمارة والملك والرئاسة هيضحي بالإسلام ويتركه ويتمسك بالإمارة،\nوطبعا مش هقول لكم على الظلم والقهر إللي ممكن واحد زي ده يعمله في الناس،\nوالأسوأ بقى إنه يتبعوا واحد زي ده ويتركوا الإسلام هم كمان ودي لوحدها كارثة\nعشان كده رسول الله ﷺ كان بيرفض يعطي الإمارة أو الزعامة لأي حد يطلبها وكان يقول ﷺ:\n\"إنا والله لا نُوَلّي هذا العمل أحداً سأله ولا أحداً حرص عليه\"\nلأنه ساعتها بيكون مفتون بالإمارة،\nده غير إن رسول الله ﷺ نهى عن إن حد يطلب الإمارة أصلا، قال مرة لواحد من الصحابة اسمه عبد الرحمن بن سَمُرَة :\n\" يا عبد الرحمن بن سمرة لا تسأل الإمارة؛ \nفإنك إن أُعطِيتَها عن غير مسألة أُعِنْت عليها وإن أُعطِيتَها عن مسألةٍ وُكِلت إليها\"\nيعني الواحد ميروحش يطلب الولاية ولا الحكم على الناس، لكن لو حد رشحه أو أعطاه الولاية مفيش مشكلة بل بالعكس ده ربنا يعينه عليها،\nفلما رسول الله ﷺ سمع رسالة هوذة قال:\n\" لو سألني قطعة من الأرض ما فعلت\"\nيعني بيقول ده لو قال لي هات حتة أرض بس مش هديله، يقوم يطلب إمارة المسلمين،\nثم قال:\n\"بَادَ وبَاد ما في يديه\"\nوفعلا تحققت نبوءة رسول الله ﷺ وبعد أقل من سنتين مات هوذة بن علي وفقد ملكه ولم يُسلم، يعني لا طال دنيا ولا آخرة\n☆طيب هنا في سؤال،\nإزاي رسول الله ﷺ بيقول إنه لا يعطي الولاية لحد سألها ومينفعش طلب الولاية؛ ويوسف عليه السلام قال لعزيز مصر اجعلني على خزائن الأرض، يعني هو هنا طلب الولاية أهه\nالإجابة هنا في نقطتين:\n◇الأولى:\nإنَّ شرعَ من قبلنا شرعٌ لنا ما لم يُنسَخ، يعني يوسف عليه السلام له شرع بيحكم به، واحنا لنا شريعة الإسلام، لو مفيش حاجة في شريعة الإسلام تنسخ أو تعارض الشرائع السابقة يبقى عادي ناخد بيها،\nلكن لو في حاجة في شريعتنا تنسخ الشريعة السابقة يبقى نتبع شريعة الإسلام، زي مثلا في شريعة داوُد عليه السلام كان جائز فيها بناء التماثيل، لكن في شريعة الإسلام حرام بناء التماثيل،\nكذلك في شريعة يوسف عليه السلام كان جائز إنه يطلب الإمارة، لكن في شريعة الإسلام عندنا نهي في طلب الإمارة، والنهي هنا نهي التحريم، يعني يَحرم طلب الإمارة\n◇النقطة الثانية:\nإن يوسف عليه السلام شاف إن المصلحة في إن هو إللي يمسك وزارة المالية؛ لأنه شاف إن المال ضائع ويُفَرّط به ومفيش أمانة والناس داخلين على مجاعة فأراد إنه ينقذ البلد من كارثة محققة وإنه يزيل سوء التدبير وسوء العمل إللي كان حاصل للبلد ساعتها وهوالوحيد القادر على كده،\nوده بقى جائز في شرعنا احنا كمان\nيعني يجوز للمسلم إنه يطلب الإمارة إذا شاف المصلحة والخير للمسلمين إنه يطلب الإمارة ويكون هو الحاكم أو المدير أو الرئيس أو....أو...\nيعني لو هو شايف نفسه أهل للإمارة وإن الأمور ضائعة ومحدش غيره هيقدر يصلح الأوضاع، وإن إللي بيحكم ليس أهل للحكم؛ فهنا جائز إنه يطلب الإمارة ويكون هو الحاكم أو المدير أو الرئيس أو غيره\nوالدليل على كده إن واحد من الصحابة اسمه عثمان بن أبي العاص الثقفي قال لرسول الله:\n\"اجعلني إمام قومي\"\nفقال له رسول الله ﷺ : \n\"أنت إمامهم واقتدِ بأضعفهم\"\nفهنا رسول الله ﷺ مأنكرش عليه طلبه للإمارة؛ لأنه شاف إن المصلحة معاه هو وهمه إنه يصلح شؤون قومه ومش قصده الدنيا ولا عايز إللي عند الناس\n☆يبقى خلاصة الكلام إن طلب الإمارة محرم إلا لو في مصلحة وخير مُحقق للمسلمين على يد مَن يطلب الإمارة ومفيش غيره\nنشوف الزعيم الخامس إللي رسول الله ﷺ أرسل له رسالة،\nهو:\n◇الحارث بن أبي شَمِر أو شُمّر الغَسّاني،\nوالحارث ده كان أمير دمشق وكان على النصرانية وكان تابعا لهرقل ملك الروم،\nأرسل له رسول الله ﷺ رسالة مع الصحابي شُجاع بن وهْب\nيقول له فيها:\n\" بسم الله الرحمن الرحيم من محمد رسول الله إلى الحارث بن أبي شمر سلام على من اتبع الهدى وآمن به وصدق،\n وإني أدعوك إلى أن تؤمن بالله وحده لا شريك له يبقى لك ملكك\"\nفلما وصلته الرسالة كان رد فعله زي رد فعل كسرى تقريبا، رمى رسالة رسول الله ﷺ وقال بكل كِبر:\nمن يَنزِعُ ملكي مني\nوأنا سائر إليه\nيعني هو مين ده إللي يقدر ياخد مني ملكي، طيب أنا هجهز جيش وهروح أقاتله وأهزمه وهنشوف مين إللي هينزع ملك التاني،\nوفعلا بدأ يجهز الجيوش عشان يروح يغزو المدينة، لكن قبل ما يخرج كان عايز يستأذن هرقل لأنه تابع له فأرسل الحارث برسالة لهرقل يحكي له فيها على إللي حصل وإنه هيروح يغزو المدينة،\nرسالة الحارث وصلت لهرقل في نفس الوقت إللي وصلت فيه رسالة رسول الله ﷺ لهرقل، وهنعرف رد فعل هرقل بعدين على رسالة رسول الله ﷺ، \nفأرسل هرقل للحارث يمنعه من الخروج لقتال رسول الله ﷺ وقال له ميستعجلش ويستنى لحد ما يشوفوا إيه إللي هيحصل بعد كده،\nفسمع الحارث كلام هرقل ولم يُرسل الجيوش لغزو المدينة،\nولما عرف رسول الله ﷺ برد فعل الحارث قال:\n\"باد ملكه\"\nوفعلا صدقت نبوءة رسول الله ﷺ معداش وقت طويل إلا ومات الحارث وانتهى ملكه، ومش بس كده ده ملكه هيدخل في ملك المسلمين بعدين \nالملك السادس إللي رسول الله ﷺ أرسل له رسالة هو:\n◇النجاشي أصْحَمة ملك الحبشة\nاحنا اتكلمنا عن قصة إسلام النجاشي بالتفصيل في الجزء الرابع والعشرين فمش هعيد الكلام عنها،لكن هتكلم عن حدثين مهمين حصلوا،\nرسول الله ﷺ أرسل للنجاشي رسالة يدعوه فيها للإسلام زي باقي الملوك،\nوكان حامل الرسالة هو الصحابي عمرو بن أمية الضِّمري،\nوالنجاشي زي ما قلنا قبل كده كان مُخفي لإسلامه واتكلمنا عن السبب في كده،\nفلما جاء عمرو بن أمية الضمري للنجاشي أكرمه النجاشي ورد على رسالة رسول الله ﷺ بأنه بيبايعه على الإسلام وإنه تابع له، وظل النجاشي على الإسلام لحد ما مات في السنة التاسعة للهجرة وصلى عليه رسول الله ﷺ صلاة الغائب لأن مكنش في مسلمين معاه في البلد،\nعمرو بن أمية الضمري كان له مهمة تانية غير تسليم رسالة رسول الله ﷺ للنجاشي، المهمة دي كانت إنه يخطب أم حبيبة رملة بنت أبي سفيان للنبي ﷺ وده الحدث المهم الأول،\nرملة بنت أبي سفيان حاكم مكة كانت هاجرت مع المسلمين للحبشة مع زوجها عبيد الله بن جحش، وكانت حامل في ابنتها حبيبة ولما ولدت بقت كنيتها أم حبيبة واشتهرت بالكُنية دي،\nمات عبيد الله بن جحش في الحبشة وبقت أم حبيبة لوحدها هناك،\nوفي رواية بتقول إن عبيد الله بن جحش تنصر بعد ما أسلم ومات على النصرانية، لكن الرواية دي ضعيفة والراجح إنه مات على الإسلام ولم يتنصر،\nالمهم إن أم حبيبة دلوقتي من غير زوج، فأرسل رسول الله ﷺ للنجاشي مع عمرو بن أمية إنه يزوجه أم حبيبة،\nفأرسل النجاشي لأم حبيبة جارية تخبرها بأن رسول الله ﷺ يطلبها للزواج ففرحت أم حبيبة بالبشرى دي ووكلت ابن عمها عنها ليزوجها،\nفدفع لها النجاشي نيابة عن رسول الله ﷺ صداق أو مهر أربعمائة دينار، وعمل لها وليمة للعرس،\nورجعت أم حبيبة للمدينة لرسول الله ﷺ ودخل بها رسول الله ﷺ وكان عمرها خمسة وثلاثين عام وفي رواية تانية كان عمرها اثنان وأربعون عام،\nوفي زواجها نزلت الآية:\n\"عَسَى اللَّهُ أَنْ يَجْعَلَ بَيْنَكُمْ وَبَيْنَ الَّذِينَ عَادَيْتُمْ مِنْهُمْ مَوَدَّةً \"\nوالمودة هنا قيل إنها صلة القرابة إللي حصلت بين رسول الله ﷺ وبين بني أمية، \nلأن رسول الله ﷺ بقى زوج بنت زعيم قريش إللي هو من بني أمية، فلما أبو سفيان عرف إن رسول الله ﷺ تزوج بنته خفّت البغضاء والكُره في قلب أبي سفيان على رسول الله ﷺ،\nوفي موقف زواج رسول الله ﷺ من أم حبيبة دعوة إلى مقابلة السيئة بالحسنة،\nفعلى الرغم من العداوة والإساءة إللي أبو سفيان آذى بها رسول الله ﷺ لكن رسول الله ﷺ تزوج بنته،\nوهو بكده أحسن لأبي سفيان، ومقابلة السيئة بالحسنة تؤدي إلى دفع وزوال الحقد والكُره وصفاء النفوس بين المتخاصمين\nوبكده يبقى رسول الله ﷺ متزوج من:\n◇سودة بنت زمعه رضي الله عنها.\n◇عائشة بنت أبي بكر الصديق رضي الله عنها.\n◇ حفصة بنت عمر رضي الله عنها.\n◇أم سلمة هند بنت أبي أمية المخزومية رضي الله عنها.\n◇زينب بنت جحش رضي الله عنها \n◇جويرية بنت الحارث رضي الله عنها\n◇ أم حبيبة رملة بنت أبي سفيان رضي الله عنها.\n☆الحدث المهم التاني هو إسلام عمرو بن العاص على يد النجاشي، سبحان الله واحد من العرب يسلم على يد واحد من غير العرب\nإزاي ده بقى حصل\nخلونا نرجع بالزمن كده للأحداث بعد غزوة الأحزاب أو غزوة الخندق، قلنا إن قريش رجعت لمكة خائبة ومقدرتش تقضي على رسول الله ﷺ مع إن الجيش إللي كان محاصر المدينة  كان عشرة آلاف مقاتل،\nلما رجعوا لمكة عمرو بن العاص قعد مع مجموعة من قريش كانوا بيسمعوا لآراءه وعارفين مكانته بين الناس وعارفين رجاحة عقله وما عنده من الدهاء والتفكير، \nفاقترح عليهم اقتراح، قال لهم:\nوالله إني أرى أمر محمداً يعلو الأمور علواً منكراً، وإني قد رأيت أمراً، فما ترون فيه؟\nيعني بيقول لهم إنه شايف إن دين رسول الله ﷺ بدأ يظهر ودولته بدأت تقوى وده خطر عليهم فلقى حل عشان يطلع من الأزمة دي،\nفسألوه: \nوماذا رأيتَ\nيعني إيه رأيك وإيه الحل إللي عندك،\nقال لهم عمرو:\n\"رأيتُ أن نلحق بالنجاشي فنكون عنده، فإن ظَهر محمد على قومنا كنا عند النجاشي، فإنَّا أن نكون تحت يديه أحب إلينا من أن نكون تحت يدي محمد، \nوإن ظهر قومنا فنحن مَنْ قد عرفوا، فلن يأتينا منهم إلا خير\"\nيعني بيقول لهم إننا نروح الحبشة عند النجاشي نقعد عنده ونشوف الصراع بين محمد وقريش هيوصل لحد فين، \nلو محمد هو إللي انتصر وبقى له الغلبة يبقى احنا عند النجاشي تحت حكمه،\nولو قومنا هم إللي انتصروا فهم عارفينا كويس وعارفين إننا في صفهم ومش هيجيلنا منهم إلا كل خير،\nفعجبهم رأي عمرو وقالوا خلونا نجمع هدايا للنجاشي ونروح له بيها، وكان النجاشي بيحب الجلد فجمعوا له هدايا من الجلد وانطلقوا للنجاشي،\nطبعا الأحداث دي مكنتش بين يوم وليلة، ده خدوا لهم وقت على ما راحوا عند النجاشي\nولما وصلوا للحبشة قعدوا فترة على ما دخلوا قصر النجاشي، \nفلما دخلوا عنده شافوا رسول رسول الله ﷺ عمرو بن أمية الضمري خارج من عند النجاشي،\nوكان ساعتها عمرو بن أمية بيكلم النجاشي في أصحاب رسول الله ﷺ وإن رسول الله ﷺ أمر بإنهم يرجعوا للمدينة خلاص؛ لأن الأمور استقرت في المدينة والإسلام مبقاش مهدد بالزوال زي قبل كده،\nفكان الهدف من وجود مجموعة من الصحابة في الحبشة هو الحفاظ على أصل الإسلام، لكن بعد ما الأوضاع استقرت خلاص أمر برجوعهم،\nفالمجموعة من قريش بقيادة عمرو بن العاص شافوا عمرو بن أمية وهو خارج من عند النجاشي،\nفقال لهم عمرو بن العاص :\nده عمرو بن أمية الضمري، لو دخلت على النجاشي وسألته إنه يعطيه لي فأقتله؛ قريش هتشوف إني عملت فيهم جميل لما قتلت رسول محمد\nفأصحابه شجعوه ودخل فعلا عمرو بن العاص على النجاشي،\nوكان من عادة الناس ومنهم عمرو إنهم لما يدخلوا على الملوك إنهم يسجدوا لهم كنوع من التحية لهم،\nطبعا النجاشي المسلم مكنش يعرف حرمة السجود لغير الله لأن كان في شرائع كتير مكنش يعرفها بسبب بعده عن رسول الله ﷺ،\nوكمان تحريم السجود لغير الله كان حصل متأخر فكده كده النجاشي مكنش يعرف بيه،\nالمهم إن عمرو دخل على النجاشي وسجد له كعادته، فقال له النجاشي:\nمرحبا بصديقي، أهديت إليّ من بلادك شيئا؟\nيعني بيقول له إنت جبت لي حاجة من معاك من بلادك، \nواحنا قلنا قبل كده إن كان في علاقة صداقة بين عمرو بن العاص وبين النجاشي، \nفقال له عمرو :\nنعم أيها الملك، قد أهديت إليك أُدمًا كثيرا، يعني جابله جلود كثيرة، فقرب له الجلود فعجبت النجاشي واشتهاها،\nوهنا استغل عمرو الموقف وقال للنجاشي:\nأيها الملك، أنا شوفت رجل خرج من عندك، وهو رسول رجل عدو لنا، فأعطنيه لأقتله، فإنه قد أصاب من أشرافنا وخيارنا،\nيعني قتل ناس من أشرافنا وأحسنِنَا،\nفالنجاشي غضب جدا ومد يده فضرب بها أنفه ضربة شديدة ظن عمرو إنه كسر أنفه،\nفخاف عمرو من النجاشي ومن شدة خوفه تمنى إن الأرض تنشق وتبلعه\nوبعدين قال للنجاشي:\nأيها الملك، والله لو كنت أعرف إن كلامي مش هيعجبك وهتكره طلبي مكنتش طلبته منك\nفقال النجاشي لعمرو:\nانت بتطلب مني أعطيك رسول رجل يأتيه الناموس الأكبر الذي كان يأتي موسى لتقتله\n☆الناموس الأكبر هو جبريل عليه السلام،\nفقال عمرو للنجاشي:\nهو فعلا كده، بيجيله الوحي زي ما بيقول\nفقال له النجاشي:\nويحك يا عمرو أطعني واتبعه، فإنه والله لعلى الحق وليظهرن على من خالفه، كما ظهر موسى على فرعون وجنوده\nيعني النجاشي بيدعو عمرو للإسلام وبيقول له إن رسول الله ﷺ حق ودينه حق وهينتصر على كل أعدائه في النهاية زي ما موسى عليه السلام انتصر على فرعون وجنوده،\nفقال له عمرو:\nأفتبايعني له على الإسلام؟\nيعني عمرو عايز يبايع النجاشي على الإسلام مكان رسول الله ﷺ لحد ما عمرو يذهب لرسول الله ﷺ،\nفقال له النجاشي نعم وبسط يده وبايع عمرو على الإسلام،\nوخرج عمرو من عند النجاشي وهو مسلم وأخفى إسلامه عن أصحابه عشان محدش فيهم يقتله ولّا حاجة\nوالأحداث دي كانت في بدايات السنة السابعة من الهجرة،\nبعد فترة انطلق عمرو للمدينة عشان يبايع رسول الله ﷺ على الإسلام، والموضوع ده له قصة تانية هنعرفها لما ييجي وقتها إن شاء الله\nكده مش فاضل غير رسالة رسول الله ﷺ إلى هرقل ملك الروم ودي هنعرفها الجزء الجزء الجاي إن شاء الله \n♡"}, {"n": 159, "l": "الجزء 133 | رسائل رسول الله الي الملوك الجزء الثالث | رسالة رسول الله الي هرقل | بين هرقل وابو سفيان", "u": "https://www.facebook.com/groups/710210019782034/permalink/836459747157060/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#رسائل_رسول_الله_إلى_الملوك_الجزء_الثالث\n#رسالة_رسول_الله_لهرقل\n#بين_هرقل_وأبو_سفيان\nاتكلمنا عن أهم رسائل رسول الله ﷺ إلى ملوك زمانه يدعوهم فيها إلى الإسلام وشوفنا ردود أفعالهم المختلفة،\nاتبقى لنا رسالة رسول الله ﷺ إلى هرقل ملك الروم ورد فعله عليها،\nرسول الله ﷺ أرسل رسائل تانية لزعماء مختلفين غير إللي اتكلمنا عنهم وبعضهم رد فعله كان سبب في وقوع قتال بينهم وبين المسلمين زي ما هنشوف بعدين إن شاء الله\nلكن أول ملوك رسول الله ﷺ أرسل لهم رسائل هم السبعة إللي قلنا عليهم،\nآخر واحد من الملوك السبعة دول هو:\n◇هِرَقْل ملك الروم.\nهرقل ده كان بيحكم نصف مساحة العالم في زمن رسول الله ﷺ،\nيعني دولة الروم كانت تحكم نصف الأرض ودولة فارس كانت بتحكم النصف الثاني،\nوكان في حروب بين فارس والروم عشان كل واحد يفرض سيطرته ويُظهر قوته،\nالروم كانوا أهل كتاب على النصرانية والفرس كانوا على المجوسية يعبدون النار،\nحصل حرب بين فارس والروم لما كان رسول الله ﷺ والصحابة لسه في مكة قبل الهجرة بحوالي ثلاثة أو أربع سنين تقريبا\nوالنتيجة كانت انتصار الفرس على الروم،\nكفار قريش كانوا بيحبوا إن فارس تنتصر على الروم لأنهم زيهم أهل أوثان، \nفلما انتصر الفُرس فرح كفار قريش بانتصار الفرس وقالوا للصحابة احنا كمان هنغلبكم زي ما فارس غلبت الروم\nالصحابة كانوا بيحبوا إن الروم هم إللي ينتصروا لأنهم أهل كتاب وهم أقرب لهم،\nفلما انهزم الروم الصحابة زعلوا وراحوا لأبي بكر الصديق رضي الله عنه وحكوا له إللي حصل،\nفذهب أبو بكر وأخبر رسول الله ﷺ بالحكاية، فقال له رسول الله ﷺ:\n\" أَمَا إِنَّهُمْ سَيَغْلِبُونَ \"\nونزلت سورة الروم قال تعالى:\n\"غُلِبَتِ الرُّومُ ۩ فِي أَدْنَى الْأَرْضِ وَهُم مِّن بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ ۩ فِي بِضْعِ سِنِينَ ۗ لِلَّهِ الْأَمْرُ مِن قَبْلُ وَمِن بَعْدُ ۚ وَيَوْمَئِذٍ يَفْرَحُ الْمُؤْمِنُونَ \"\nيعني الروم اتغلبوا دلوقتي لكنهم في بضع سنين هيغلبوا الفرس ، والبضع هو العدد أقل من العشرة ولكن لا يقل عن الثلاث،\nفقال أبو بكر الكلام ده للمشركين فقالوا له :\n\" اجْعَلْ بَيْنَنَا وَبَيْنَكَ أَجَلًا ، فَإِنْ ظَهَرْنَا كَانَ لَنَا كَذَا وَكَذَا ، وَإِنْ ظَهَرْتُمْ كَانَ لَكُمْ كَذَا وَكَذَا\"\nيعني خلي في بيننا ميعاد محدد لو انتصر الفرس يبقى تعطيني كذا وكذا، ولو الروم انتصروا هنعطيكم كذا وكذا،\nفحدد لهم أبو بكر الصديق ميعاد خمس سنين،\nلكن الروم منتصروش برده، فالمشركين كده يُعتبر كسبوا الرهان فقال لهم إن القرآن قال في بضع سنين والبضع زي ما قلنا هو ما دون العشر،\nيعني لسه عندنا وقت، وفعلا بعدها بأربع سنين في عام الحديبية تحديدا انتصر الروم على الفرس زي ما القرآن قال.\nوكان هرقل نَذر لله إن لو ربنا نصره على الفرس هيحج من حِمْص لبيت المقدس ماشي على رجله،\nوانتم عارفين إنه ملك، والملوك دائما بيركبوا على الدواب  على سرير المُلك،\nفهو عشان يعني يظهر شكره لله نذر إنه هيحج لبيت المقدس على قدميه،\nوكان النصارى بيحجوا لبيت المقدس زي ما المسلمين بيحجوا للكعبة كده،\nبعد ما وصل هرقل لبيت المقدس وصلته رسالة رسول الله ﷺ مع الصحابي دِحْيَة الكلبي\nخلونا كده نشوف رسالة رسول الله ﷺ لهرقل ملك الروم بتقول إيه:\nقال رسول الله ﷺ:\n\" بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. \n\"مِنْ مُحَمَّدٍ عَبْدِ اللَّهِ وَرَسُولِهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ،\n سَلاَمٌ عَلَى مَنِ اتَّبَعَ الْهُدَى،\n أَسْلِمْ تَسْلَمْ، يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ، فَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ 《الأَرِيسِيِّينَ》،\nقُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ اللَّهِ ۚ فَإِن تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ \"\nعشان تتصوروا موقف هرقل\nإيه رأيكم لما واحد في قرية صغيرة في أفريقيا محدش يسمع بيها يرسل رسالة لرئيس أمريكا ويطلب منه إنه يتبعه،\nأكيد طبعا رئيس أقوى دولة في العالم هيتعامل مع الموضوع بسخرية، هو مين ده إللي بيطلب مني إني اتبعه\nأهه ده كان الموقف قصاد هرقل، دولة بسيطة نشأت في بلاد العرب إللي الرومان أصلا بينظروا لهم نظرة دونية،\nوإنهم أقل من أن حد يهتم بشؤونهم أو حتى يدرس أحوالهم،\nالعرب إللي كانوا عايشين على إغارة بعضهم على بعض وبُعاد عن كل مظاهر الحضارة والمدنية،\nوفي الآخر يطلع واحد منهم يهدد أقوى ملك على ظهر الأرض ساعتها بعد هزيمته لفارس ويقول له :\n\"أسلم تسلم\" \nرد الفعل المتوقع من هرقل إنه هيعمل زي كسرى على الأقل،\nده إن مجمعش جيش وراح يجتاح المدينة\nلكن المفاجأة إن هرقل تعامل مع رسالة رسول الله ﷺ بمنتهى الجِدية، خصوصا إنه كان وصل له خبر إن في رجل خرج وبيقول على نفسه إنه نبي،\nفعرف إن إللي أرسل له الرسالة دي مش واحد عادي\nده واحد بيتكلم بكل عِزة وفخر وعنده الجرأة إنه يهدد أعظم ملك على وجه الأرض،\nوالتهديد إللي في الرسالة ده تهديد مينفعش يستهين بيه،\nثم معنى إنه يذكر له كلمة《الأَرِيسيِّين》، فأكيد الرجل عنده علم مش عند غيره، أمّال إزاي عرف التاريخ المَخفي إللي النصارى بيحاولوا يُخفوه\nوهرقل كان زعيم نصراني أه، لكنه كان متدين وملتزم إلى حد كبير بتعاليم النصرانية، \nوكان يقرأ في التوراة والإنجيل وعارف الأحداث إللي حصلت من بعد عيسى عليه السلام، وعارف إن في نبي بشّر به عيسى عليه السلام هيخرج في آخر الزمان وهو نَفْسه كان منتظر خروج النبي ده،\nفدلوقتي جاءت له رسالة من الرجل إللي بيقول على نفسه نبي، يبقى لازم ياخد الموضوع على مَحْمل الجد \nبدأ هرقل فعلا يبحث في الموضوع وأمر جنوده إنهم يبحثوا عن بعض العرب إللي من نفس بلد الرجل إللي بيدعي إنه نبي،\nجنود هرقل بدأوا يبحثوا في فلسطين عن أي عرب موجودين في المنطقة وفعلا لقوا مجموعة من العرب من قريش كمان وأخذوهم عشان يقابلوا هرقل.\n☆والسبب في وجود المجموعة دي في الشام أو فلسطين إنهم خرجوا للتجارة بعد صلح الحديبية،\nلأن دلوقتي بقى في أمان بينهم وبين رسول الله ﷺ بعد الصلح إللي حصل بينهم بعد ما كانت قوافل قريش لا تأمن على قوافلها، والتجارة للشام كانت كل شوية تتعرض للهجوم،\nفهم استغلوا الفرصة وخرجوا بعد صلح الحديبية على طول للتجارة في الشام،\nوبتقدير من الله عز وجل تزامنت كل الأحداث مع بعض، وجود هرقل في إيلياء أو فلسطين إللي جاء من حمص ومجيء دِحْية الكلبي برسالة رسول الله ﷺ ومجيء قافلة قريش\nالمهم،\nدخلوا على هرقل وقال للمترجم يسألهم إذا كانوا يعرفوا الرجل العربي إللي خرج من بلادهم وبيقول عن نفسه إنه نبي ولّا لأ، فقال له زعيمهم إنهم يعرفوه، فسأل عن أقربهم نسبا لرسول الله ﷺ، \nفقال زعيم القافلة إن هو أقرب نسباً لمحمد ﷺ،\nمين بقى كان زعيم القافلة دي\nأبو سفيان زعيم مكة\nأمره هرقل إنه يتقدم وجعل باقي أصحابه وراء ظهره بحيث إنه لا يراهم، وقال للمترجم يقول لهم:\nأنا هسأله أسئلة لو كذب عليّ ردوا عليه وكذبوه\n☆أي حد في الموقف ده هيبقى عايز يستغل الفرصة عشان ينتقم من عدوه إللي مش قادر عليه بقال سنين حتى لو بالكذب\nلكن أبو سفيان كان سيد في قومه يأنف الكذب، ولولا إنه مش عايز الناس تُعيّره بعد كده إنه كذب على هرقل كان كذب براحته،\nوأبو سفيان نفسه قال:\n\"فوالله لولا الحياء من أن يَأْثر أصحابي عني الكذب لكذبته حين سألني عنه، ولكني استحيَيْت أن يأثروا الكذب عني فصَدَقْتُه\"\nمع إن إللي ينظر للواقع ميظنش إن أصحاب أبو سفيان ممكن يعيّروه بالكذب لأنهم كمان عايزين ينتقموا من رسول الله ﷺ،\nيعني زي ما بنقول كلهم في الهوا سوا\nوأبو سفيان قال:\nوالله لو كذبت ما ردوا عليّ كذبي\nولكن الكذب مكنش من أخلاق العرب، كانوا بيشوفوا إن الكذب ده شيء سيء لا يليق بأخلاقهم وبيعتبروه نوع من الضعف وخصوصا ساداتهم.\nبدأ هرقل يسأل أبا سفيان عن رسول الله ﷺ أسئلة واضحة ومحددة وفي حضور عِلية القوم من الأمراء والوزراء والعلماء من الرومان، قال هرقل :\nكيف نَسبُه فيكم؟\nيعني هل هو شريف ونسبه عالي ولّا مجرد واحد وضِيع مجهول النسب،\nقال أبو سفيان: هو فينا ذو نسب! يعني نسبه عريق ومن سادات العرب.\nقال هرقل: \nفهل قال هذا القول من قبلكم أحدٌ قَطُّ قبله؟\nيعني في حد ادعى النبوة قبل الرجل ده ولّا هو أول واحد يقول الكلام ده،\nفقال أبو سفيان: لا، لم يدَّعِ أحدٌ في تاريخ العرب النبوة.\nيعني أول مرة واحد من العرب يقول الكلام ده.\nفقال هرقل: هل كان من آبائه من مَلِك؟\nفقال أبو سفيان: لا.\nقال هرقل: فأشراف الناس اتبعوه أم ضعفاؤهم؟\nيعني أتباعه هم رؤساء وعِلية القوم الأقوياء ولّا الناس الضعفاء الفقراء،\nقال أبو سفيان: بل ضعفاؤهم\nقال هرقل: أيزيدون أم ينقصون؟\nقال أبو سفيان: بل يزيدون.\nقال هرقل: فهل يرتد أحد منهم سَخْطةً لدينه بعد أن يدخل فيه؟\nيعني بعد ما الواحد منهم يدخل في الإسلام بيرتد لأنه لقى الدين ده سيء،\nقال أبو سفيان: لا، لا يرتد منهم أحد.\n◇وهنا في دليل على إن زوج  أم حبيبة رملة بنت أبي سفيان عبيد الله بن جحش لم يتنصر زي ما في بعض الروايات بتقول وقلنا إنها ضعيفة المرة إللي فاتت،\nلأنه لو كانت تنصر كان زمان أبو سفيان استغل الموقف وقال أيوة زوج بنتي ارتد بعد ما دخل في الإسلام، لكن محصلش، فده يثبت إن عبيد الله بن جحش مات على الإسلام\nقال هرقل: فهل كنتم تتهمونه بالكذب قبل أن يقول ما قال؟\nيعني الرجل ده كان معروف عنه إنه بيكذب على الناس،\nقال أبو سفيان: لا.\n◇واحنا عارفين إن رسول الله ﷺ كان يُلقب بالصادق الأمين قبل البعثة\nقال هرقل: فهل يغدر؟\nيعني لو حد عاهده عهد ممكن يغدر وينقض العهد،\nفقال أبو سفيان: لا،\nونحن منه في مدةٍ لا ندري ما هو فاعل فيها\n☆أبو سفيان كان عايز يطعن على رسول الله ﷺ بأي شيء لكن مش عارف، \nفلما هرقل سأله السؤال ده حب يستغل الموقف ويُدخل الشك في قلب هرقل بحيث إنه يُشوّه صورة رسول الله ﷺ بأي طريقة،\nفقال له احنا في بيننا هُدنة دلوقتي ومنعرفش هو ناوي يعمل إيه في المستقبل، يعني بيرمي لهرقل إن في احتمال إنه يغدر في المستقبل،\nوأبو سفيان نفسه قال:\n\" ولم تُمْكِنِّي كلمةٌ أُدخل فيها شيئًا غير هذه الكلمة\"\nلكن هرقل ولا اهتم أصلا بكلام أبي سفيان، وكمل أسئلته عادي جدا\nقال هرقل:\nفهل قاتلتموه؟ يعني حصل بينكم حرب،\nقال أبو سفيان: نعم.\nفقال هرقل: فكيف كان قتالكم إياه؟ يعني كانت إيه النتيجة القتال بينكم،\nقال أبو سفيان: الحرب بيننا وبينه سجال! يعني مرة نفوز ومرة هو يفوز،\nقال هرقل: بماذا يأمركم؟ يعني بيقول لكم تعملوا إيه،\nقال أبو سفيان:\nيقول: اعبدوا الله وحده، ولا تشركوا به شيئًا، واتركوا ما يقول آباؤكم، ويأمرنا بالصلاة والصدق والعفاف والصلة.\n☆سبحان الله، أبو سفيان على الرغم من إنه كان مشرك لكنه كان عارف رسالة الإسلام بتدعو لإيه بالتحديد،\nفي حين إن في مسلمين في زماننا دلوقتي ميعرفوش عن الإسلام غير اسمه فقط، \nومش بس كده ده في منهم إللي بيطعن في الإسلام وبيقول إنه خلاص مبقاش ينفع في زماننا دلوقتي\nالأسئلة إللي هرقل سألها لأبي سفيان دي لها معنى كبير جدا، هو مسألش أي أسئلة كده وخلاص ده كل سؤال بيثبت إن الرجل إللي بيقول عن نفسه نبي هو فعلا رسول من عند الله\nبدأ هرقل يشرح لأبي سفيان ولكل الحاضرين هو ليه سأل الأسئلة دي، وكل كلمة فيها إثبات بصدق نبوة رسول الله ﷺ قال هرقل للمترجم يقول لأبي سفيان:\nسألتك عن نسبه، فقلت إنه فيكم ذو نسب، وكذلك الرّسل تُبعث في نسب من قومها\nوسألتك: هل في أحد قبله قال مثل قوله، فقلت محصلش، فقلت: لو كان في أحد قبله قال نفس الكلام بتاعه وادعى النبوة؛ كنت هقول ده رجل بيقلد إللي اتقال قبل كده،\nوسألتك: هل كان من آبائه من مَلِك؟\nفقلت لأ، فلو كان في أبائه من مَلِك، كنت هقول ده رجل بيطلب مُلك أبيه،\nوسألتك: هل كنتم تتهمونه بالكذب قبل أن يقول ما قال؟ قلت لأ، فَعرفت إنه مش هيترك الكذب على الناس ويكذب على الله\nوسألتك: أشراف الناس اتبعوه أم ضعفاؤهم؟ فقلت إن ضعفاءهم هم إللي اتبعوه، وهم دول أتباع الرسل\n☆فاكرين قصص الأنبياء، احنا شوفنا إن كل أتباع الرسل كانوا من المستضعفين \nوسألتك: هل يزيدون أم ينقصون؟ فقلت إنهم يزيدون، وكذلك أمر الإيمان حتى يتم.\nوسألتك: هل في حد بيرتد منهم سَخْطَةً لدينه بعد أن يدخل فيه؟ \nفقلت لي لأ، وكذلك الإيمان حين تخالط بشاشته القلوب.\nيعني لما القلب يشعر بحلاوة الإيمان بيبقى مش عايز يترك شعور الإطمئنان القلبي والراحة النفسية،\nوسألتك: هل يغدر؟ فقلت لأ، وكذلك الرسل لا تغدر\n☆بعكس أخلاق الملوك وطلَّاب السُّلطة والمنصب تحكُمهم اعتباراتُ المصلحة والسياسة، لا الأخلاق والهداية فالكذب والغدر عندهم عادي\nوسألتك: بماذا يأمر؟ فقلت إنه بيأمركم أن تعبدوا الله، ولا تشركوا به شيئًا، وينهاكم عن عبادة الأوثان، ويأمركم بالصلاة والصدق والعفاف والصلة وهذه دعوة الأنبياء.\nبعد ما شرح هرقل لأبي سفيان ولكل الحاضرين وجهة نظره قال كلمة عجيبة \nقال:\n\"فَإِنْ كَانَ مَا تَقُولُ حَقًّا فَسَيَمْلِكُ مَوْضِعَ قَدَمَيَّ هَاتَيْنِ،\n وَقَدْ كُنْتُ أَعْلَمُ اَنَّهُ خَارِجٌ، \nولَمْ أكُنْ أَظُنُّ أَنَّهُ مِنْكُمْ، فَلَوْ أَنِّي أَعْلَمُ أَنِّي أَخْلُصُ إِلَيْهِ لَتَجَشَّمْتُ لِقَاءَهُ، وَلَوْ كُنْتُ عِنْدَهُ لَغَسَلْتُ عَنْ قَدَمِهِ\"\nيعني بيقول لأبي سفيان إن رسول الله ﷺ دولته هتكبر وهتقوى وهتنتشر في الأرض لدرجة إن المسلمين هياخدوا من هرقل ملكه ويحكموا المكان إللي هو قاعد فيه\nوهو كان عارف إن نبي آخر الزمان هيخرج بس كان مفكر إنه هيخرج من الشام كالعادة مش من العرب،\nوبيقول له لولا إني أخاف إني مقدرش أوصل له والطريق هينقطع عليه لاجتهدت في الوصول إليه، ولو أنا عنده دلوقت لغسلت له قدميه.\nمتخيلين إن ده كلام ملك أعظم دولة في زمن رسول الله ﷺ \nبعد ما أنهى هرقل كلامه أمر واحد من جنوده إنه يأتيه برسالة رسول الله ﷺ إللي أرسلها مع دِحية الكلبي،\nوقرأها على الحاضرين كلهم، والمترجم كان بيترجم للغة الرومانية،\nحصل صَخب ودوشة وأصوات الناس بدأت تعلى في المجلس بكلمات اعتراض على رسالة رسول الله ﷺ،\nطبعا معترضين ومش عاجبهم رسالة رسول الله ﷺ،\nأمر هرقل الجنود بإخراج أبي سفيان وأصحابه من المجلس،\nخرجوا وهم في حالة ذهول من كلام هرقل إللي سمع عن رسول الله ﷺ مرة واحدة بس، \nوهم عاشروه سنين ومع ذلك بيكذبوه، ده غير رسالة رسول الله ﷺ إللي سمعوها وهو بيهدد فيها ملك أعظم دولة في ذلك الزمن،\nفلما خرج أبو سفيان قال لأصحابه وهو في منتهى الذهول:\n لَقَدْ أمِرَ أَمْرُ ابْنِ أَبِي كَبْشَةَ، إِنَّهُ يَخَافُهُ مَلِكُ بَنِي الأصْفَرِ‏ \n☆ابن أبي كبشة يقصد به رسول الله ﷺ، وقيل إن أبي كبشة نسبة لزوج حليمة السعدية فهو أبو رسول الله ﷺ من الرضاع، وقيل نسبة لجد رسول الله ﷺ من ناحية أمه، فكانت قريش لما تحب تقلل من شأن رسول الله ﷺ تنسبه لجده أبي كبشة.\nفأبو سفيان بيقول إن أمر رسول الله ﷺ عَظُم جدا وانتشر لدرجة إن ملك بني الأصفر إللي هم الروم خايف من رسول الله ﷺ،\nفكل الأحداث دي تركت أثر كبير جدا في نفس أبي سفيان،\nوساعتها أيقن أبو سفيان إن رسول الله ﷺ هيظهر على الناس ودينه هينتشر\nبعد كل كلام هرقل ده واقتناعه التام بإن محمد ﷺ نبي آخر الزمان، هل أسلم هرقل؟\nثم إيه حكاية الأريسيين دي\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 160, "l": "الجزء 134 | رسائل رسول الله الي الملوك الجزء الرابع | رد فعل هرقل على رسالة رسول الله | الأريسيين", "u": "https://www.facebook.com/groups/710210019782034/permalink/836471310489237/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#رسائل_رسول_الله_إلى_الملوك_الجزء_الرابع\n#رد_فعل_هرقل_على_رسالة_رسول_الله\n#الأَرِيسِيِّين\nاتكلمنا المرة إللي فاتت عن الحوار إللي حصل بين هرقل وأبو سفيان، ووصول رسالة رسول الله ﷺ إلى هرقل،\nوشفنا إن هرقل أقر واعترف إن محمد ﷺ رسول من عند الله،\nهرقل استدعى رئيس الكهنة وكان اسمه ضَغاطِر أو صَفاطِر وكان له مكانة عظيمة جدا عند الكهنة وعامة الناس وكلمته مسموعة أكثر من هرقل نفسه،\nفأخبره برسالة رسول الله ﷺ وفي رواية تانية إن هرقل أرسل له دحية الكلبي برسالة رسول الله ﷺ عشان يستشيره،\nالمهم يعني إن ضغاطر وصلت له رسالة رسول الله ﷺ،\nفلما قرأها ضغاطر وسأل دحية الكلبي شوية أسئلة عن رسول الله ﷺ فلقى إن كل المعلومات بتشير إلى إن محمد ﷺ هو نبي آخر الزمان إللي بشّر به عيسى عليه السلام،\nفقال ضغاطر لهرقل:\nأنا مصدقه وهتبعه\n فقال له هرقل إنه مش هيقدر يعمل زيه؛ لأنه لو اتبع محمد ﷺ ملكه هيزول والكهنة مش هيسكتوا ومش بعيد يقتلوه،\nفآثر هرقل إنه يحافظ على ملكه في مقابل عدم الدخول في الإسلام،\nأما ضغاطر فأسلم، وقال لرسول النبي ﷺ دحية الكلبي :\nأَقرِئ صاحبك مني السلام وقل له أني أشهد أن لا إله إلا الله وأن محمدا رسول الله ، وإني آمنت به وصدقته \nفخرج ضغاطر على الأساقفة وأخبرهم بإسلامه ودعاهم لاتباع نبي آخر الزمان لكنهم رفضوا واجتمعوا عليه وقتلوه رحمه الله.\n☆والأساقفة دول هم رؤساء القساوسة يعني الأُسقف أعلى منزلة عند النصارى من القسيس.\n◇احنا ممكن نشوف قصة ضغاطر إنها قصة واحد أسلم وقُتل وخلاص وعدت،\nلكن الموضوع مش بسيط أبدا، انتم متخيلين واحد له مكانة عظيمة جدا مش بس بين عامة الناس لأ ده حتى بين كبار رجال الدولة ومش بس كده ده مكانته وكلامه في نفوسهم أعظم من مكانة هرقل نفسه وكلامه بيمشي على الكل،\nومع ذلك ساب كل ده وقاوم نفسه الأمارة بالسوء وفتنة الدنيا ودخل في دين محدش يعرف عنه حاجة،\nوهو مش بس هيفقد كل المميزات إللي عنده دي،لأ، ده كمان هيعرّض نفسه للقتل وده واحد ميعرفش عن الإسلام غير لا إله إلا الله محمد رسول الله،\nميعرفش حتى إزاي يصلي، ومع ذلك أخذ القرار باتباع رسول الله ﷺ \nعشان نتخيل مع بعض حاجة بسيطة بس من إللي ضغاطر كان فيها؛ لو واحد فينا عرف إن شغله إللي بياكل منه وبيصرف بيه على أهل بيته فيه حاجة تغضب ربنا هل هيقدر ياخد القرار بإنه يسيب الشغل ده فورا؟\nبلاش دي هناخد مثال أبسط من كده، \nالأفراح المختلطة إللي مليانة محرمات من أغاني وتبرج للنساء ورقص ومعاصي بالكوم،\nلو حد فينا اتعزم فيها من أخوه أو أخته أو أي أحد من قرايبه هيرفض إنه يروح لأنه مكان يغضب الله ولّا هيقول ده فرح أخويا أو فرح أختي إزاي محضرش فرحهم،\nوالناس هتقول إيه وأخويا هيزعل و مبررات كتير ويلاقي صعوبة كبيرة جدا إنه ياخد قرار زي ده\nودي حاجة بسيطة جدا لو قارناها بموقف ضغاطر\nفضاغطر لأنه كان صادق مع الله وكان عايز يرضي الله بجد ومكنش مُدّعي؛ ربنا سهل عليه إنه ياخد قرار الدخول في الإسلام ومهمهوش هو هيفقد إيه من المميزات إللي عنده ولا همه رد فعل الأساقفة ولا حتى همه إنه هيتعرض للقتل،\nلأنه هو عارف كويس أوي إن مهما كانت مُتع الدنيا والمناصب والمكانة بين الناس فهو هيسيب كل ده ومش هينفعه غير عمله وكل إللي هو فيه لا يُقارن أبدا بجنة عرضها السماوات والأرض،\nفمين إللي يضحي بجنة عرضها السماوات والأرض عشان منصب ولّا شوية مُتع كلها كم ساعة وهيتركها ويموت\nهرقل عرف بمقتل ضغاطر فقال لدحية رضي الله عنه إن ضغاطر كان أعظم مكانة منه عند الأَساقفة ومع ذلك قتلوه فلو هو أسلم بقى هيعملوا معاه إيه\nوأخذ هرقل رسالة رسول الله ﷺ وحفظها في قَصَبة من ذهب إكراما لها، والقصَبَة حاجة كده زي أنبوب مُجوف يعني أنبوبة فاضية من الداخل،\nفعلق رسول الله ﷺ على فعل هرقل بإنه قال:\nهرقل أمسكها فلن يزال الناسُ يجدون منه بأسًا ما دام في العيشِ خيرٌ\nيعني طول ما هم حافظين لرسالة رسول الله ﷺ الملك هيفضل فيهم،\nعشان كده الرومان كانوا بيتوَارثوا رسالة رسول الله ﷺ وكان الآباء يوصون الأبناء إن مادام الكتاب ده عندهم فالمُلك هيفضل فيهم،\nوبعض قادة المسلمين وسفرائهم شافوا رسالة رسول الله ﷺ عند ملوك الروم على مر السنين، وكان ملوك الروم بيفتخروا برسالة رسول الله ﷺ لهرقل وبيقولوا لهم أد إيه هم محافظين على الرسالة دي وبيعظموها وبيتوارثوها عشان الملك يستمر فيهم.\n◇في رواية ذكرها أهل السِّيَر بتقول إن هرقل جمع الأساقفة وعظماء الروم في بناء زي القصر كده وأمر الجنود إنهم يقفلوا الأبواب من الخارج،\nوخرج عليهم هرقل وبدأ يكلمهم ويقول لهم:\nيا معشر الروم! هل لكم في الفلاح والرّشد وأن يثبت ملككم فتبايعوا هذا النبي؟\nيعني بيقول لهم لو عايزين الملك بتاعكم يستمر وكمان تحصلوا الفوز في الآخرة اتبعوا نبي آخر الزمان،\nفحصل هرج ومرج وقام الناس وانطلقوا ناحية الأبواب عايزين يخرجوا فلقوا الأبواب مقفولة،\nفلما شاف هرقل نفورهم عن كلامه ويَأِس من إيمانهم قال للجنود رجعوهم تاني، فقال لهم:\nإني قلت مقالتي آنِفًا أختبر شِدّتكم على دينكم فقد رأيتُ\nيعني بيقول لهم أنا قلت الكلام إللي قلته عشان أختبر دينكم وأشوفكم هتفضلوا ثابتين عليه ولاّ ممكن تغيروه بسهولة،\nفسجدوا له جميعا ورضوا عنه.\n◇الله أعلم الرواية دي صحيحة ولّا ضعيفة لكن العلماء ذكروها وهم بيتكلموا عن هرقل، \nفسواء كانت الرواية دي صحيحة أو ضعيفة،فالشاهد يعني إن هرقل لم يُسلم وآثر الملك والحياة الدنيا على الآخرة،\nولو كان صادق في كلامه إنه كان مستني نبي آخر الزمان كان زمانه على الأقل أسلم سرا زي ما النجاشي عمل\nوعلى فكرة موقف هرقل ده بيتكرر معانا بس في مواقف مختلفة، \nيعني مثلا واحد يقول أنا والله عايز ربنا يهديني فأول ما ألاقي وظيفة واستقر هبدأ أصلي والتزم بالدين،\nوفعلا ربنا يرزقه بالوظيفة ويخليه يستقر عشان يشوف هيعمل إيه ويوريله نفسه هيعمل إيه، فتلاقيه لا صلي ولا التزم بالدين،\nوواحدة تقول أنا ناوية ألبس الحجاب الشرعي الصحيح أول ما أتزوج على طول، فربنا يرزقها بالزواج ومتتحجبش برده،\nعارفين كمان زي إيه \n زي موقف بني إسرائيل في قصة طالوت وجالوت، لما قالوا لنبي لهم احنا عايزين ملك نقاتل معاه ولما ربنا أعطاهم إللي طلبوه رفضوا واعترضوا إلا قليل منهم،\nربنا بيعطينا الشرط إللي بنطلبه عشان نشوف احنا هنعمل إيه :\n\"فَيَنْظُر كَيْفَ تَعْمَلُونَ \"\nولو الإنسان صادق؛ عمره ما يأخر التوبة ولا الالتزام بدين الله لأي سبب من الأسباب زي ما ضغاطر عمل،\nضغاطر كان منتظر نبي آخر الزمان هو كمان ولأنه كان صادق أول ما وصل له الخبر تنازل عن كل حاجة حتى حياته في مقابل الدين، وخصوصا إنه كان من 《الأَرِيسِيِّين》 \nمين هم بقى الأَرِيسِيِّين أو الأَرْيُسِيِّين إللي رسول الله ﷺ ذكرهم في رسالته لهرقل وقال :\n\"فَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ 《الأَرِيسِيِّينَ》\"\nلما العلماء شرحوا الحديث، قالوا إن كلمة الأَرِيسِيِّينَ معناها الفلاحين،\nيعني رسول الله ﷺ بيقول لهرقل لو انت مش عايز تدخل في الإسلام فلا تقف حائل بين الفلاحين وبين الإسلام،\nلكن لو الكلام ده صحيح فاشمعنا الفلاحين، طيب وفين باقي البشر إللي عايشين في الدولة الرومانية، هرقل مش هيشيل وزرهم لو منعهم من الدخول في الإسلام\nعشان كده حصل اضطراب بين العلماء وهم بيفسروا معنى الكلمة دي، لكن اتضح إن كلمة الأَرِيسِيِّينَ بتشير لمعنى تاني خالص ووراها قصة مَخفيّة،\nعشان نعرف أصل القصة محتاجين نرجع بالزمن إلى الوقت إللي رُفع فيه عيسى عليه السلام إلى السماء،\nلو تفتكروا في الحلقة الأولى من السيرة قلنا إن بعد رفع عيسى عليه السلام تفرق الحواريين أتباع عيسى إللي كانوا على التوحيد الدين الذي جاء به عيسى عليه السلام وبقوا يدعوا الناس له،\nوكان للحواريين أتباع، ولكن اليهود مكنوش بيسيبوهم وكانوا بيحرضوا ملوك الرومان عليهم ويقولوا لهم إن الناس دي هيخربوا ملككم، \nفكانت الملوك تعذب من يتبع الحواريين فكانوا بيؤمنوا في السر، وحتى الحواريين نفسهم اتعرضوا للتعذيب الشديد جدا،\nوكان من أكثر الناس إللي كانت بتعذب الحواريين واحد من علماء اليهود  اسمه《شاوُل الطرسُوسِي》،\nبعد فترة شاوُل ده ادّعى إنه آمن بالمسيح بعد ما قابله وهو راجع من دمشق وإنه عاتبه إزاي يعذب أصحابه العذاب الشديد ده، \nوادعى إن المسيح أمره بنشر تعاليم دينه بين الأمم، لكن مش كل الحواريين صدقوه، البعض كذبه والبعض صدقه،\nكان من إللي صدقه واحد من الحواريين اسمه بِرنابا وبدأ يدافع عنه وقدمه إلى الحواريين فقبِلُوه ، \nوبما يمتلكه شاوُل من حدة ذكاء وقوة حيلة استطاع إنه يأخذ مكان مرموق بين الحواريين واتسمى بـ بولس،\nونجح الخبيث ده فى تغيير دين المسيح من دين إلاهى كان أرقى من اليهودية مكملا لها وتحويله إلى طقوس وثنية، ونجح في إللي كان اليهود عايزينه، بإنهم يلغوا دين المسيح عشان ميكنش لهم منافس،\nوكان الحواريون قد هربوا لأماكن مختلفة من العالم وبدأوا ينشروا دين عيسى إللي هو التوحيد أو الإسلام بين الناس،\nواحنا بنقول الإسلام لأن الدين عند ربنا واحد وهو الإسلام مع اختلاف الشرائع،\nوكانوا بيعلموا بعض عن طريق رسائل بيبعتوها لبعض،\nوشاول سافر مع برنابا لروما عشان ينشروا دين النصرانية هناك،\nحصلت خلافات كثيرة بينهم بعدين وتفرقوا عن بعض وكل واحد منهم راح في طريق،\n الدولة الرومانية إللي كانت على الوثنية مكنتش بتسيب الحواريين ولا أتباعهم، كانوا بيعذبوهم وقتلوا من الحواريين وأتباعهم ناس كثيرة، وقتلوا شاول أو بولس زي ما سمى نفسه وقتلوا برنابا،\nواتعرّض النصارى لمذابح كثيرة جدا على مدار السنين كان أشدها قسوة في عهد دقلديانوس سنة 284 ميلاديا،\nفهو صمم إنه مش هيتوقف عن قتل النصارى إلا لما توصل الدماء لحد ركبة فرسه\nوفضل اضطهاد النصارى وتعذيبهم مستمر لحد ما مسك حكم الرومان الملك قُسْطَنطِين العظيم،\nقُسْطَنطِين كان بيعبد الأوثان وكان سمح بالحرية الدينية والتعايش بين النصارى وبين الوثنية،\nلكن قُسْطَنطِين شاف التفرّق إللي كان فيه النصارى، وكثْرة خلافاتهم وصراعاتهم المذْهبية؛ يعني طائفة بتقول إن عيسى رسول من عند الله وليس بإله،\nوناس بتقول إنه إله وناس بتقول إنه ابن إله، فهو كان عايز الدين يبقى واحد والناس كلهم يمشوا عليه،\nوالأوضاع المضطربة دي هتأثر على استقرار الدولة الرومانية،\n فتدخّل عشان يَعْتمد مذهب طائفة من طوائفهم ويكون هو المذهب السائد، فدعا إلى مَجْمع كَنَسي،\nفأمر بجمع كل كبار القساوسة في الامبراطورية عشان يناقشوا قضية ألوهية المسيح ويتفقوا على منهج واحد، \nوكانت معظم الكنائس موجودة على أراضي الدولة الرومانية،\nفجاء كبار القساوسة واجتمعوا في 《نِقيّة》 واتعرف المَجْمع ده باسم 《مَجمَع نِقية》،\nفاجتمع الأساقفة عشان يناقشوا قضية تألِيه المسيح،\nوكان أغلبية إللي حضروا على دين عيسى عليه السلام الصحيح دين التوحيد، إللي بيقول إن عيسى عبد الله ورسوله،\nوكان القساوسة دول لهم تلاميذ وأتباع وبيعلموا الناس دين عيسى الصحيح،\nالملك قُسْطَنطِين كان على الوثنية وتعدد الآلهة عند الرومان ده كان حاجة عادية، وكمان إن الإله يتزوج ويخلف برده كان شيء عادي،\nفكان يميل لعقيدة التثليث وإن عيسى إله ابن إله، وكان رافض تماما لفكرة توحيد الله،\nوكان على العقيدة دي بعض كبار القساوسة إللي لهم مصالح، وتمت كتابة وثيقة تُقر بألوهية المسيح لأول مرة في تاريخ النصرانية،\nوأمر قُسْطَنطِين كل الموجودين من كبار القساوسة إنهم يوقعوا عليها، كل إللي على دين المسيح الصحيح رفضوا في البداية،\n لكن مع التهديد بالقتل وهم عارفين بطش الرومان والمجازر إللي كانوا بيعملوها، وكمان هم عايزين يرجعوا لكنائسهم وتلاميذهم عشان يعلموهم ويكملوا دعوة المسيح،\nلأنهم لو قُتلوا كلهم دعوة المسيح هتكون في خطر فعلا؛\nفقالوا خلاص خلونا نوقّع على الوثيقة دي ونمشي من هنا ومش حتة ورقة يعني مضينا عليها مُكرهين هي إللي هتعمل أزمة\nوفعلا وقّعُوا على الوثيقة دي، \nما عدا ثلاثة فضلوا مصممين على رأيهم، كان من الثلاثة دول واحد اسمه:\n《آريُوس》 \nوآريوس ده كان وقف ضد أسقف مدينة الإسكندرية في دعوته لتأليه المسيح وبدأ يدعو الناس للتوحيد،\nووصلت دعوته ليُوسَابيُوس رفيق دربه وكان هو كمان على عقيدة التوحيد ، ووصلت الدعوة لباقي الكنائس المسيحية فأعلن الجميع تأييدهم لدعوة آريوس،\nوبعد كده أعلن أساقفة كنائس العالم تأييدهم لدعوة آريوس، \nيعني هو مكنش أُسقف عادي كان له مكانة عالية جدا بين الأساقفة، فكان طبيعي إنه يقف بالمرصاد للوثيقة إللي أصدرها قُسْطَنطِين،\nبعد ما الأساقفة وقَّعوا حصلت المفاجأة\nقُسْطَنطِين أمر بعزل ونَفْي كل إللي رفضوا التوقيع في البداية ورافضين لمذهب تأليه المسيح\nوأمر بتعيين مكانهم قساوسة يؤمنوا بعقيدة تأليه المسيح،\nلأن قُسْطَنطِين وإللي معاه عارفين إن الأساقفة وقّعوا مُكرهين وناويين يرجعوا لدعوة التوحيد،\nوكانت نتيجة المجمع تقرير ألُوهية المسيح - عليه السلام - وأنَّه ابنُ الله -  تَعالى الله عن قولهم - وقرَّروا أنَّ هذا الإله تجَسَّد في صورة البشر؛ لِخَلاص الناس ثم ارتفع إلى السماء \nولأن آريوس كان أكثر واحد مُعاند ومعروف بمعارضته الشديدة لفكرة تأليه المسيح أصدروا قرار بلعن آريوس وحرق كتبه وكتب كل مَن معه من الموحدين، وأي حد هيتبع آريوس هيتعرض للتعذيب والقتل،\nوطبعا بما إن الأقوى هو إللي بيكتب التاريخ، فهم نسبوا كل إللي على دين المسيح الصحيح لآريوس وسموهم 《الأريسيين》\nوإللي بدلّوا دين عيسى عليه السلام وقالوا بألوهيته سموا نفسهم 《الآرثُوذُكس》، ومعناها الأصُولِيين، يعني إللي ييتبعوا أصل الدين المسيحي \nفبقى لما يُقال أريسيين يبقى هم دول إللي غلط، لكن الآرثُوذُكس هم الصح واتقلبت الآية،\nوأتباع التوحيد كانوا بيرفضوا لفظ الأريسيين ده ويقولوا احنا أتباع المسيح مش أتباع آريوس،\nلكن أعداءهم عايزين يشوهوا صورتهم، ويصرفوا نظر عامة الناس عن القصة الحقيقية للأريسيين،\nظن أعداء التوحيد إنهم انتصروا على آريوس وقضوا على دعوة التوحيد،\nلكن ربنا له تقدير تاني، وزي ما أخرج من قصر فرعون مَن يؤمن بموسى عليه السلام ويحميه من صغره، كذلك أخرج من قصر قُسْطَنطِين من يؤمن بدين التوحيد ويساعد \nالمستضعفين إللي بيتعرضوا للتعذيب والقتل\nهيلانة أم قُسْطَنطِين العظيم الملك الروماني تدخل في المسيحية الصحيحة إللي كان يدعو لها آريوس\n\"وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ \"\nاستغلت الامبراطورة هيلانة نفوذها في المملكة الرومانية واستطاعت ترجّع كثير من الأساقفة الأريسيين لكنائسهم وتقريبهم للحاشية الملكية،\nوكان من الأساقفة إللي قربتهم يوسابيوس صاحب آريوس،\nويوسابيوس مع علمه بالمسيحية كان سياسي حكيم\nفبدأ يوسابيوس يناقش الامبراطور قُسْطَنطِين العظيم بكل هدوء وحكمة عن حقيقة دعوة المسيح للتوحيد،\nوإن الدعوة إللي بيدعوا لها آريوس مش حاجة جديدة وهي نفسها الدعوة إللي جاء بها الكتاب المقدس وهي توحيد لله بالعبادة، وشوية شوية بدأ قُسْطَنطِين يُعجب بكلام يوسابيوس، وعرف حجم الكارثة إللي عملها لما أصدر وثيقة تأليه المسيح\nودخل قسطنطين في دين المسيحية الصحيحة على منهاج آريوس، \nوحاول إنه يصلح إللي عمله لكن مش هينفع يعزل كل الأساقفة إللي عيّنهم مرة واحدة؛ هتحصل كارثة في الامبراطورية، فبدأ يسحب البساط من تحت رجلهم شوية شوية،\nلحد ما تمكن من إعادة الأساقفة إللي عزلهم قبل كده ولغى قرارات مجمع نيقية، وعفى عن آريوس واستقرت دعوة التوحيد،\nوأرسل قسطنطين في طلب آريوس عشان يرجع مرة ثانية، وفعلا رجع آريوس والناس استقبلوه بالحب والترحاب في الشوراع، وكان لما رجع أكل من طعام الكنيسة على حسب طقوسهم،\nوهو ماشي وسط الناس وقع في الأرض وبدأ يرجع دم وجاله إسهال شديد ودي أعراض تسمم،\nومات آريوس مسموما، واستقرت دعوة التوحيد، وقبل ما يموت قسطنطين وزع الامبراطورية على أولاده الثلاثة،\nكل واحد فيهم اتبع المذهب السائد في المكان إللي أخذه،\nفواحد شجع عقيدة التوحيد إللي كان ينادي بها آريوس،\nوواحد ثاني شجّع عقيدة التثليث،\nوبعد فترة تم توحيد الامبراطورية الرومانية على يد ابن قسطنطين إللي كان يتبع مذهب آريوس وفرض عقيدة التوحيد على الناس،\nلكن بعد موته جاء للحكم مَلِك روماني يدعو لعقيدة التثليث وإن عيسى إله وبدأ التنكيل والقتل والتعذيب في أتباع دين التوحيد أو زي ما سموهم:\n《الأريسيين》\nوكان من الأريسيين دول الرجل النصراني صاحب غلام أصحاب الأخدود إللي اتكلمنا عنه في أول حلقتين من السيرة\nعرفتم ليه ضغاطر وهرقل أيقنوا إن محمد ﷺ كان رسول من عند الله، مش أي حد يعرف تاريخ الأريسيين عند النصارى، فما بالكم لما يطلع واحد من أعماق الصحراء من العرب يقول لملك الروم فإن لم تسلم فإن عليك إثم الأريسيين\nقصة الأريسيين قصة طويلة وفيها أحداث كثيرة وأسماء تانية أنا مقلتهاش عشان الأسماء هتلغبطكم\nفأنا قلت لكم المختصر المفيد،\nومصادر القصة هتلاقوها في التعليقات\n:\n《حلقات آريوس لجهاد الترباني، وحلقات الآريسييين لدكتور فاضل سليمان، وكتاب : أقباط مسلمون قبل محمد ﷺ للدكتور فاضل سليمان》\nاسمعوا الفيديوهات هتستفيدوا كتير والحلقات جميلة وممتعة ومش هتزهقوا منها وهتلاقوا في الحلقات المصادر من كتب النصارى نفسهم عن الأريسيين\nإن شاء الله المرة الجاية هنرجع لرسول الله ﷺ ونتكلم عن فتح خيبر"}, {"n": 161, "l": "الجزء 135 | فتح خيبر الجزء الأول | الطريق إلى خيبر", "u": "https://www.facebook.com/groups/710210019782034/permalink/836473700488998/", "t": "مشكله كبيره هتواجه رسول الله وهيا مشكلة المنافقين \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#فتح_خيبر_الجزء_الأول\n#الطريق_إلى_خيبر\nاتكلمنا في الأجزاء الأخيرة إللي فاتت عن رسائل رسول الله ﷺ إلي ملوك وزعماء زمانه وشوفنا ردود أفعالهم،\nفي نفس الوقت إللي رسول الله ﷺ أرسل فيه الرسائل مع السفراء بدأ يجهز جيش يروح يكمل القتال بينه وبين اليهود في خيْبَر\nقبل ما نبدأ في الكلام عن أحداث خيبر، عايزين نتكلم عن نقطة مهمة وهي:\n السفراء إللي رسول الله ﷺ أرسلهم للملوك،\nاحنا قلنا قبل كده إن كل حاجة رسول الله ﷺ بيعملها وراها حكمة وتفكير وتدبير،\nوإنه مش بياخد أي قرار كده وخلاص، وخصوصا إنه قدوة للأمة الإسلامية كلها ويجب اتباعه،\nفلما نيجي نشوف السفراء إللي رسول الله ﷺ أرسلهم هنلاحظ إنهم:\n◇أولا: \nالسفراء كلهم كانوا يتصفون باللّباقة والكياسة والذكاء والدهاء وحسن الحوار،\nواحنا شوفنا في حوار المقوقس وحاطب بن أبي بلتعة إزاي حاطب كان بيدعو المقوقس للإسلام وشوفنا اختياره للألفاظ،\nفرسول الله ﷺ مكنش بيختار أي حد، كان بيختار الشخص الصحيح إللي ينفع للمهمة \nوده هياخدنا للنقطة الثانية وهي:\n◇إن رسول الله ﷺ مكنش بيختار السفراء على أساس القبيلة ولا أساس درجة القرابة منه ﷺ،\nيعني السبع سفراء دول كانوا كلهم من قبائل العرب المختلفة ما عدا واحد فقط وهو عبد الله بن حُذافة السهمي، \nومش هنلاقي أي حد من بني هاشم قبيلة رسول الله ﷺ خرج في المهمة دي، فرسول الله ﷺ بيوصل رسالة للجميع إن إللي يتولى المهام هم الأصلح والأكفأ بغض النظر عن النسب والمكانة العائلية،\nوإن القائد الحقيقي هو إللي يهتم بمصلحة الأمة مش مصلحة القبيلة ويهتم بقضايا الرعية مش قضايا العائلة\n☆ ممكن تطلع وجهة نظر تقول:\nمش كان الأفضل إن رسول الله ﷺ يجعل كل السفراء من قريش، وبكده هترتفع قيمتهم عند الزعماء دول على أساس إن قريش قبيلة عربية مشهورة\nحتى لو وجهة النظر دي صحيحة؛ في المقابل هيبقى في رسالة عكسية سلبية وهي:\nإن السفارة لا تكون إلا في أشراف الناس، وده مش صحيح، لأن الأكفأ والأفضل هو إللي يتولى المهمة بغض النظر قبيلته أو مكانته إيه\n◇الملاحظة الثالثة هي إن كل السفراء كانوا من المهاجرين مفيش فيهم ولا أنصاري واحد، ودي حاجة هنلاحظها على مدار السيرة، إن محدش من الأنصار مسك منصب هام أو قيادي في الدولة الإسلامية، \nمع إن الأنصار يُعتبروا هم حجر الأساس في قيام دولة الإسلام، \nولعل السبب في كده هو إن الأنصار يستمروا في كونهم رمز للعطاء مش الأخذ، \nفالصفة إللي تميز الأنصار هي صفة الإيثار، ومننساش طبعا في أحداث بيعة العقبة الثانية لما الأنصار سألوا رسول الله ﷺ عن المقابل إللي هيأخذوه مقابل نصرة الإسلام ورسول الله ﷺ وعدهم بالجنة،\nيعني مفيش أي مناصب في الدنيا كله في الآخرة، فكان الأنصار هم مَضرب المثل في خُلق الإيثار،\nلأنهم كانوا بيعطوا عطاء بلا حدود وبدون انتظار أي مقابل في الدنيا،\nومرة واحد من الأنصار جاء لرسول الله ﷺ وقال له:\n يا رسول الله! ألا تستعملني كما استعملت فلاناً؟\n فقال ﷺ وهو بيكلم الأنصار : إنكم ستلقون بعدي أَثَرَة، فاصبروا حتى تلقوني على الحوض\"\nيعني رسول الله ﷺ بيقول للأنصار إن الناس هتنفرد عنكم بأمور كثيرة وانتم مش هيكون لكم حاجة مع إنكم أصحاب حق فيها، فاصبروا ومتطلبوش الإمارة لحد ما تقابلوني على الحوض،\nوده عشان الأنصار يفضلوا رمز ومثال واضح ونقي لخُلق الإيثار\nنرجع بقى لقصة خيبر،\nمنطقة خيبر دي كانت من أكبر التجمعات اليهودية في الجزيرة العربية، بل هي كانت أكبر التجمعات على الإطلاق في الوقت ده،\nواحنا عارفين إن ملف اليهود مع رسول الله ﷺ ملف أسود\nشوفنا بني قينقاع وشوفنا بني النضير وشوفنا بني قريظة، كل قبيلة منهم كان لها كارثة مع رسول الله ﷺ،\nوآخرهم كانوا يهود خيبر، فاكرين طبعا غزوة الأحزاب وإن المُحرك الرئيسي لها كان اليهود في خيبر،\nده طبعا غير المؤامرات إللي عملوها بعد الأحزاب ضد رسول الله ﷺ والمسلمين واتصالهم بالمنافقين في المدينة عشان يضعفوا شوكة المسلمين،\nوقلنا إن بعد غزوة الأحزاب رسول الله ﷺ كان بيرسل السرايا عشان يؤدب القبائل إللي شاركت في غزوة الأحزاب،\nوقلنا إن رسول الله ﷺ كان عايز يحل مشكلة يهود خيبر، بس المشكلة إنه كان لازم هيغيب عن المدينة فترة طويلة لكن مينفعش يسيب المدينة من غير ما يكون فيها مقاتلين؛\nلأنه كان خايف إن قريش تهجم على المدينة ويضطر كده يحارب جيشين في نفس الوقت جيش مكة وجيش اليهود،\nيعني كده هيحط نفسه بين فكّي كماشة،\nلكن دلوقتي هو خلاص أمّن نفسه من قريش فهيبقى تركيزه كله في قتال يهود خيبر\nرسول الله ﷺ كان مستعجل في الخروج لليهود لقتالهم في خيبر، فهو خرج بعد أقل من شهر من صلح الحديبية في شهر محرم، وده القول الراجح، في أقوال تانية بتقول إنها كانت في شهر صفر وأقوال إنها كانت في شهر ربيع الأول،\nلكن الراجح زي ما قلنا إنها في شهر محرم،\nوسبب استعجال رسول الله ﷺ لفتح خيبر أنه كان لا يأمن غدر قريش وحلفائها،\nيعني قريش ممكن تغدر في أي وقت، عشان كده حب يستغل فرصة إن الصلح لسه في البداية فيتحرك بسرعة،\nوسبب تاني هو:\nإن اليهود أكيد هيوصل لهم خبر صُلح قريش مع رسول الله ﷺ، \nولأنهم عارفين تاريخهم الإسود مع رسول الله ﷺ والمسلمين فأكيد هيتوقعوا إن هيكون في هجوم عليهم قريب، وبالتالي هياخدوا احتياطاتهم ويستعدوا للقتال،\nعشان كده كل ما كان رسول الله ﷺ أسرع في الهجوم كان ده في مصلحة المسلمين\nوالسبب الثالث في استعجال رسول الله ﷺ لقتال اليهود هو إنه ﷺ كان عايز يرفع معنويات المسلمين المُنكسرة بعد صلح الحديبية، \nلأنهم مكنوش لسه شافوا الخير إللي ترتب على صلح الحديبية، يعني مثلا مراسلة الملوك والزعماء مكنتش نتيجتها ظهرت لسه،\nلأن رسول الله ﷺ أرسل الرسائل من هنا وجهز جيش المسلمين للخروج لخيبر من هنا،\nوطبعا عشان الواحد يسافر ساعتها للأماكن البعيدة دي محتاج شهر رايح وشهر راجع على الأقل\nفلسه متضايقين من الصلح إللي حسوا إنهم مظلومين فيه،\nوربنا كان بشرهم في سورة الفتح بغنائم يأخذوها، \nفكل ده كان لرفع معنويات الصحابة:\n\" وَعَدَكُمُ اللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا\"\nلكن في مشكلة كبيرة هتواجه رسول الله ﷺ \nوهي مشكلة المنافقين\nثبت لرسول الله ﷺ خيانة المنافقين وإن في تعامل بينهم وبين اليهود، \nولو خرجوا معاه في الجيش أكيد هيعملوا مشاكل وخيانتهم هتتكرر وده هيأثر على جيش المسلمين ورسول الله ﷺ مش عايزهم معاه في الجيش،\nوطبعا رسول الله ﷺ ميقدرش يقوم ويقول للمنافق انت متخرجش معانا عشان انت منافق\nلأن النفاق ده حاجة قلبية، واحنا ملناش غير الظاهر، والمنافقين كانوا بيُظهروا الإسلام، فمش هينفع يقول للمنافقين إنهم ميخرجوش،\nطب إيه الحل\nالحل إن رسول الله ﷺ يُعلن في الناس إن محدش يخرج للقتال في خيبر غير الألف وأربعمائة إللي شهدوا صلح الحديبية \nودول كلهم كانوا مؤمنين، ربنا شهد لهم بكده في القرآن:\n\"لَّقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ\"\nلكن طبعا الأعراب والمنافقين إللي تخلفوا عن رسول الله ﷺ في الحديبية مسكتوش، \nطلبوا من رسول الله ﷺ إنهم يخرجوا معاه لما عرفوا إنه هيروح خيبر وربنا وعده بفتح خيبر، وخيبر دي مليانة بالخيرات والثمار يعني زي ما ربنا مغانم كثيرة\n\"سَيَقُولُ الْمُخَلَّفُونَ إِذَا انْطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ \"\nلكن رسول الله ﷺ أعلن إن محدش هيروح معاه خيبر غير إللي حضروا صلح الحديبية،\n\"قُلْ لَنْ تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ اللَّهُ مِنْ قَبْلُ\"\nخرج جيش المسلمين المكون ألف وأربعائة مقاتل باتجاه خيبر، وطبعا زي ما رسول الله ﷺ توقع \nأرسل المنافقون إلى يهود خيبر يخبروهم بقدوم رسول الله ﷺ وجيش المسلمين لخيبر،\n لأ وكمان شجعوهم على قتال رسول صلى الله ﷺ وقالوا لهم: \nمتخافوش منهم، ده أعدادهم قليلة ومعاهم أسلحة قليلة، وانتم أعدادكم أكبر وأسلحتكم أقوى وأكثر منهم\nوصلت رسالة المنافقين لأهل خيبر، فبدأوا يستعدوا للقتال وتحصّنوا داخل حصونهم،\nومش بس كده، ده أرسلوا واحد من زعماء اليهود اسمه كِنانَة بن أبي الحقيق إلى قبائل غَطفان المُرتزقة وعرضوا عليهم المال عشان يساعدوهم ويعاونوهم في حرب المسلمين.\n☆بالمناسبة،\nكِنانة بن أبي الحقيق ده هو أخو أبو رافع سلّام بن أبي الحقيق إللي قتله المسلمين في سرية عبد الله بن عتِيك،\nواتكلمنا عن قصة اغتياله في الجزء السادس والتسعون لو تفتكروا\nالمهم،\nكنانة بن أبي الحقيق عرض على قبائل غطفان نصف ثمار خيبر في مقابل مساعدتهم لهم في قتالهم ضد المسلمين،\nفوافقوا وبدأت قبائل غطفان تجهز جيش لمساعدة اليهود في خيبر، \nلكن عيون رسول الله ﷺ أو خلونا نقول مخابرات رسول الله ﷺ اكتشفت تحرك قبائل غطفان وعرف إنهم عايزين يساعدوا اليهود في خيبر،\nفبسرعة رسول الله ﷺ أخذ قرارات سريعة عشان يُأَمّن خطة هجومه على حصون خيبر\n◇أولاً: \nقام بتأمين المدينة؛ لأن المدينة دلوقتي مفيهاش مقاتلين وتقريبا فاضية، \nفلو حصل وجاءت قبائل للهجوم على المدينة رسول الله ﷺ وجيشه هيضطر للرجوع وكمان المدينة هتتعرض للخطر\nفكان لازم تأمين المدينة\nطيب عمل إيه بقى عشان يأمنها\nجهز رسول الله ﷺ سرية بقيادة الصحابي أبّان بن سعيد رضي الله عنه وخلّاه يتجه ناحية أعراب نَجد حول المدينة عشان يُثير الرعب في المنطقة، \nوبالتالي محدش هيتجرأ إنه يهاجم المدينة سواء من قبائل غطفان أو غيرها\n◇ثانيا:\nجهز رسول الله ﷺ سرية ثانية وأمرهم إنهم يتوجهوا لديار غطفان مش لجيش غطفان، وأمر رسول الله ﷺ السرية دي إنها تُظهر أمرها ولا تتخفى، \nواحنا عارفين إن من عادة رسول الله ﷺ إنه لما كان يخرج للغزوة أو يأمر بخروج سرية كان يأمر الصحابة بالسِّرية وإنهم يتخفوا،\nلكن المرة دي أمرهم إنهم يُعلنوا أمرهم، والسبب في كده عشان يوهموا جيش غطفان إن رسول الله ﷺ خرج لغزو ديارهم مش غزو ديار اليهود، \nفيرجع جيش غطفان مرة ثانية إلى دياره ولا يشترك مع أهل خيبر في الدفاع عن حصون خيبر،\nوفعلا هو ده إللي حصل\nجيش غطفان لما سمع بسرِيّة رسول الله ﷺ رجع بسرعة  قبائله إلى دياره، وتركوا يهود خيبر يواجهوا رسول الله ﷺ  لوحدهم\n◇ثالثا:\nرسول الله ﷺ غيّر اتجاهه للوصول لحصون خيبر، يعني المفروض إنه كان هيدخل خيبر من ناحية الجنوب، \nفشاف  أدلة عشان يشوفوا له طريق تاني من ناحية الشمال يدخل منه لحصون خيبر، \nوأدلة مفردها دليل والدليل هو الرجل الخبير بطُرق الصحراء،\nوفعلا وصل رسول الله ﷺ لحصون خيبر من ناحية الشمال وبكده رسول الله ﷺ حقق أمرين أو ضرب عصفورين بحجر:\n¤أولاً:\nهيقف حائل بين غطفان وبين خيبر بجيشه، فجيش المسلمين هيفصل بين قبائل غطفان وبين مدينة خيبر.\n¤ثانياً: \nهيمنع اليهود من إنهم يهربوا إلى الشام، وبكده يُحصَر اليهود في منطقة خيبر، والطريق إلى الشمال مغلق بالجيش الإسلامي\nبجد منتهى العبقرية من رسول الله ﷺ في التخطيط للحرب، كل حاجة معمول لها حساب\nإللي ميعرفش حياة رسول الله ﷺ هيفكر إنه مجرد واحد بيعبد ربنا وبيبلغ آيات القرآن وطول النهار قاعد في المسجد وسط الصحابة،\nميعرفش عقلية رسول الله ﷺ وتخطيطه وإزاي كان بيستغل كل الطاقات إللي عنده وبيضع قدرات كل واحد في المكان الصحيح،\nمع رسول الله ﷺ مكنش في حاجة اسمها طاقة مُهدَرة ولا كان حد ملوش لازمة، كلهم كانوا مهمين في أماكنهم حسب قدراتهم،\nوده إللي احنا محتاجينه في حياتنا دلوقتي\nكل واحد فينا محتاج يعرف إيه قدراته بالضبط وهل قدراته تتناسب مع رغباته ولّا لأ؛ عشان يقدر يوظفها في مكانها الصحيح\nلأن الواحد فينا ممكن يكون عايز وحابب يكون له دور معين لكن قدراته مش مساعداه ويفضل يحاول فيها ويفشل ويجيله احباط،\nوفي نفس الوقت قدراته دي يقدر يوظفها في حاجة هو مش حاببها لكن هيبقى مُبدع فيها،\nزي مثلا قصة زيد بن ثابت إللي اتكلمنا عنه قبل كده وقلنا إنه خرج مع رسول الله ﷺ في غزوة بدر ورسول الله ﷺ رجّعه عشان كان سنه صغير،\nهو كان عايز يخرج للجهاد لكن قدراته متنفعش، لكن هو كان عنده قدرات تانية وهي القراءة والكتابة وكان حافظ لسبعة عشرة سورة من القرآن،\nفرسول الله ﷺ وجّهَهُ إلى إنه يستغل القدرات إللي عنده،\nفبقى كاتب للوحي وتعلم لغة اليهود وبقى هو المسؤل عن المراسلات بين رسول الله ﷺ وبين اليهود،\nفأظن إننا محتاجين نركز أكثر على قدراتنا ومميزاتنا ونستغلها صح بغض النظر احنا بنحبها وعايزينها أو لأ \nإن شاء الله المرة الجاية هنتكلم عن أحداث فتح حصون خيبر حصن حصن"}, {"n": 162, "l": "الجزء 136 | فتح خيبر الجزء الثاني | حصن الناعم", "u": "https://www.facebook.com/groups/710210019782034/permalink/836478180488550/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#فتح_خيبر_الجزء_الثاني\n#حصن_الناعم\nاتكلمنا المرة إللي فاتت عن السبب إللي خلي رسول الله ﷺ يتوجه لفتح خيبر، وشوفنا تخطيطه ﷺ للدخول إلى منطقة خيبر، \nوقلنا إن رسول الله ﷺ توجه لخيبر في شهر محرم،\nواحنا عارفين إن القتال في الأشهر الحُرم مينفعش، \nقال تعالى:\n\" يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ\"\nوالأشهر الحُرم دول هم : رجب وذو القعدة وذو الحجة ومُحَرّم،\n☆السؤال بقى : \nهل حُرمة القتال في الأشهر الحُرم اتنسخت ولّا إيه حكم القتال فيهم بالضبط، بما إن في سرايا وغزوات حصلت في الأشهر الحُرم\nالموضوع ده على خلاف بين العلماء، فريق قال إن حُرمة القتال في الأشهر الحرم نُسِخت، \nوفريق قال لأ، متنسختش،\nوالنسخ معناه :رفع حكم شرعي سابق، بدليل شرعي متأخر عنه،\nيعني مثلا يكون في الإسلام حكم شرعي معين الناس تعمل بيه فترة، وبعدين الحكم ده يتلغى ويأتي حكم بداله،\nزي مثلا القتال في الأشهر الحُرم، \nفي البداية كان مُحرّم، وبعدين رسول الله ﷺ أرسل سرايا قاتلت في الأشهر الحرم وحتى بعض الغزوات حصلت في الأشهر الحرم،\nطيب القول الراجح إيه\nالقول الراجح إن بِدئ  القتال في الأشهر الحُرم لا يجوز، لكن لو كان القتال للدفاع فده يجوز،\nيعني لو جيش هجم على المسلمين في أي شهر من الأشهر الحُرُم يبقى المسلمين يدافعوا عن نفسهم عادي مفيش حرمانية،\nأو الحالة الثانية إذا كان القتال امتداد لقتال سابق يبقى يجوز القتال في الأشهر الحُرم ، زي الموقف إللي احنا فيه دلوقتي،\nرسول الله ﷺ خرج لقتال اليهود في شهر محرم،\nلكن ده مش بداية القتال ده تكملة أو امتداد للقتال إللي كان قبل كده في غزوة الأحزاب،\nلأن إللي جمعوا الأحزاب إللي حاصروا المسلمين في غزوة الخندق كانوا يهود بني النُّضير إللي راحوا سكنوا خيبر وبقوا زعمائها،\nفبعد انسحاب الأحزاب بقى لسه في قتال لم يكتمل مع اليهود،\nفرسول الله ﷺ لما خرج لقتال اليهود في شهر مُحرم وهو من الأشهر الحُرم التي لا يجوز فيها البدء بالقتال؛ كان لاستكمال القتال السابق إللي كان بين المسلمين واليهود،\nيبقى خُلاصة الكلام إن القتال في الأشهر الحُرم لا يجوز إلا لو كان دفاعا أو كان امتداد لقتال سابق لم ينتهِ\n◇إللي عايز يعرف الموضوع بتفصيل أكبر هيلاقي الرابط في التعليقات من موقع الإسلام سؤال وجواب بعنوان :\n《 هل نُسخ القتال في الأشهر الحرم؟》\nوصل رسول الله ﷺ لمنطقة خيبر، ومدينة خيبر دي مدينة كبيرة ذات حصون ومزارع،\nعدد حصونها الرئيسية حوالي ثمانية حصون كبيرة، غير الحصون الصغيرة،\nوالحصن هو بناء دفاعي مُحصّن بشدة، بيكون عامل زي المبنى الكبير كده، أكيد شوفتوه هنا ولّا هنا\nممكن تعملوا بحث على جوجل وتشوفوا صورته،\nجيش المسلمين كان مُكوّن من ألف وأربعمائة مقاتل، أما  جيش خيبر فكان عشرة آلاف مقاتل\nإللي يشوف الأعداد يقول إن أكيد المسلمين هينهزموا إزاي ألف وأربعمائة يقاتلوا عشرة ألاف مقاتل\nوالمشكلة مش بس في الفرق الكبير جدا في العدد، \nده جيش المسلمين هيواجه عقبة كبيرة جدا وهي عقبة الحصون والقلاع إللي اليهود ساكنين فيها،\nلأن الهجوم على الحصون محتاج مجهود كبير جدا والمسلمين أصلا معندهمش خبرة في قتال أهل الحصون\nده غير إن جيش المسلمين محتاج مؤونة كبيرة عشان تكفيه لفترات طويلة في حصار الحصون دي،\nوالمسلمون معندهمش الإمكانيات اللازمة للحصار ده، في حين إن اليهود حصونهم قوية وعندهم داخل الحصون والقلاع بتاعتهم أكل ومية وسلاح يكفيهم سنين، والناس كانوا يقولوا على خيبر :\n\"ما لأحد بهم من طاقة\"\nيعني محدش يقدر على فتح خيبر\nمع كل ده بقى الصحابة كانت معنوياتهم عالية جدا ، وواحد من الصحابة اسمه عامر بن الأكوع قعد ينشد لهم في الطريق وكان صوته جميل جدا والصحابة كانوا مبسوطين بيه على الآخر ولا كأنهم هيواجهوا كل العقبات إللي قلناها دي\nفالصحابة مكنش هاممهم كل ده؛ لأن ربنا وعدهم إنه هيفتح لهم خيبر، وهم عارفين إن الله لا يخلف وعده\nلما وصل رسول الله ﷺ وجيش المسلمين لمنطقة خيبر كان وصولهم في الليل، \nوكان من عادة رسول الله ﷺ إنه إذا أتى لقوم في الليل ميبدأش القتال إلا في الصباح،\nفاختار ﷺ مكان وعسكر فيه، ومكان المعسكر ده كان قريب من مجموعة حصون اسمها حصون النّطَاة، على وزن حَصَاة،\nفجاء الصحابي الحُبَاب بن المنذر رضي الله عنه وقال لرسول الله ﷺ : \nيا رسول الله أرأيت هذا المنزل أنزلكَهُ الله، أم هو الرأي في الحرب؟ \nيعني بيسأل رسول الله ﷺ المكان إللي هو اختاره للمعسكر ده، هل هو أمر من عند ربنا فنسمع ونطيع، ولّا هو اختيار بشري من رسول الله ﷺ قابل للأخذ والرد،\nفقال له رسول الله ﷺ :\nبل هو الرأي\nيعني ده رأيي وهو قابل للأخذ والرد لو في رأي أحسن منه،\nفقال له الحُباب:\n\"يا رسول الله! إن هذا المنزل قريب من حصن نطاة، \nوجميع مقاتلي خيبر فيها، وهم يدرون أحوالنا ونحن لا ندري أحوالهم،\nوسهامهم تصل إلينا وسهامنا لا تصل إليهم، ولا نأمن من بيَاتهم، وهذا بين النخلات، ومكان غائر، وأرض وخِيمَة\nفلو أمرت بمكان آخر نتخذه معسكراً\"\nيعني بيقول لرسول الله ﷺ المكان إللي احنا فيه ده قريب من حصن نطاة، وكل مقاتلين خيبر فيه، وبكده هم يشوفونا من فوق الحصن ويعرفوا أحوالنا ويبدأوا يخططوا للهجوم علينا، \nده غير إنهم لما يرموا السهام علينا سهامهم بتصل لنا،أما سهامنا إذا رميناها مش بتوصل لهم، \nواحنا منعرفش عنهم حاجة لأنهم وراء الحصن،\nوكمان المكان إللي احنا فيه ده بين النخل، ممكن اليهود يتسللوا بين النخيل ويهجموا علينا بغتة،\nفالأحسن إننا نشوف مكان تاني أفضل من ده يبقى معسكر لنا، فقال ﷺ : الرأي ما أشرت به\nيعني رأيك هو الصح، وأمر رسول الله ﷺ بتغيير مكان معسكر المسلمين لمكان أفضل،\nلما جاء الصباح خرج أهل خيبر لأعمالهم، فهم كانوا أهلَ زرعٍ وحَرْثٍ، يعني حصون خيبر حواليها من الخارج مساحات كبيرة من الأرض الزراعية،\nوكان المزارعين بيخرجوا كل يوم يشوفوا الزرع بتاعهم، فلما خرجوا زي عادتهم شافوا رسول الله ﷺ والجيش أمامهم فصرخوا وهربوا راجعين للحصون وهم بيقولوا:\n\"مُحَمَّدٌ واللَّهِ، مُحَمَّدٌ والخَمِيسُ\" \nيعني جاء محمد ﷺ وجيشه، \nاليهود كانوا عارفين إن رسول الله ﷺ وجيش المسلمين خرجوا من المدينة وتوجهوا لهم عشان يقاتلوهم عن طريق المنافقين زي ما قلنا المرة إللي فاتت،\nوطبعا اليهود لما عرفوا بتحرك رسول الله ﷺ نحوهم بدأوا يستعدوا للقتال ويجهزوا الجيش،\nلكن مكنوش يعرفوا بالضبط ميعاد وصول رسول الله ﷺ،\nفكانوا بيمارسوا حياتهم عادي لحد ما في يوم اتفاجئوا بوجود رسول الله ﷺ أمامهم خارج الحصن، وده عمل ارتباك واضطراب بين صفوف اليهود،\nلما صرخ المزارعون اليهود قالَ رسول الله ﷺ:\n\"الله أكبر ،خَرِبَتْ خَيْبَرُ، إنَّا إذا نَزَلْنا بساحَةِ قَوْمٍ {فَساءَ صَباحُ المُنْذَرِينَ}\nيعني رسول الله ﷺ بيقول استبشارا باللي هيحصل: فُتحت خيبر، احنا لما ننزل في ساحة قوم قَبُح صباح المنذَرِين،\nيعني خلاص هنهزمهم ونبيدهم إبادة\nوالمنذَرين مقصود بيها هنا اليهود لأنه ﷺ بلغهم الرسالة أكثر من مرة ومع ذلك لم يتبعوه،\nوطبعا الكلام ده كان له أثر مهم على جيش المسلمين وجيش اليهود،\nبالنسبة لجيش المسلمين فهو بيذكرهم بأن النصر من عند الله عز وجل، وأن الله عز وجل أكبر من أي عدو،\nفلو انتم شايفين حصون خيبر وسلاح خيبر وأعداد خيبر أكثر بكثير منكم فاعلموا أن الله عز وجل معنا وهو ناصرنا عليهم، وبكده يرفع معنويات المسلمين\nوبالنسبة لليهود فكلام رسول الله ﷺ أوقع في نفوسهم الهزيمة النفسية، والهزيمة النفسية هي بداية الهزيمة على أرض الواقع،\nبعد ما عسكر رسول الله ﷺ في المكان الجديد جعل رسول الله ﷺ المسؤول عن تأمين المعسكر عمر بن الخطاب رضي الله عنه، وجعل المسؤول عن الغذاء والتموين وتوزيع المياه عثمان بن عفان رضي الله عنه.\nقلنا في البداية إن منطقة خيبر فيها ثمانية حصون رئيسية،\nالحصون دي فيهم خمس حصون مع بعض وثلاثة حصون تايين مع بعض، والخمس حصون دول هم خط الدفاع الاستراتيجي الأول لليهود،\nوالحصون الخمسة مقسمة إلى:\nثلاثة حصون وحصنين، \nالثلاثة حصون في منطقة اسمها النطاة إللي قلنا عليها من شوية، \nأسماء الحصون الثلاثة : ناعم، ثم الصعب بن معاذ، ثم قلعة الزبير،\nأما الحصنين الآخرين ففي منطقة اسمها الشّق،\nأول حصن قابل رسول الله ﷺ كان حصن 《ناعم》، وهو من الحصون القوية جداً في خيبر\nكان ملك حصن ناعم واحد اسمه مَرحب، ومرحب ده كانت قوته تساوي قوة ألف رجل\nفتح اليهود الحصن وخرج منه جيش هجم على المسلمين وحصل بينهم قتال لحد ما استطاع المسلمون إنهم يردوا هجوم اليهود فتراجع اليهود لحصن الناعم ودخلوا فيه،\nاستمر القتال بين اليهود وبين المسلمين عدة أيام، ولحد دلوقتي مفيش أي تقدم\nكان المسلمون بيقعدوا يريحوا بين الهجمات، \nفواحد من الصحابة اسمه محمود بن مسلمة، أخو محمد بن مسلمة إللي قتل كعب بن الأشرف إللي حكينا قصته قبل كده لو تفتكروا،\nمحمود بن مسلمة كان عايز يريّح في مكان بعيد عن الدوشة والحركة، فشاف حصن بعيد مهجور فراح قعد هناك،\nفشافوه اليهود، فقالوا مين يروح يقتله\nفقال زعيمهم مرحب أنا هروح اقتله\nفتسلل مرحب لحد ما وصل للحصن وأخذ حجر رحى كبير ورماه من على الحصن على رأس محمود بن مسلمة\nأُصيب محمود بن مسلمة إصابة شديدة جدا ورجع لمعسكر المسلمين وشافه رسول الله ﷺ وأمر إن يُطبّب، يعني أمر بعلاج جرح محمود بن مسلمة ،\nلكن ما عداش وقت بسيط إلا وكان مات رضي الله عنه،\nوكان هو أول شهيد في غزوة خيبر،\nاليهود كانوا يخرجوا من الحصن يهجموا على المسلمين والمسلمين يصدوا الهجوم، وقعدوا فترة على الحال ده والحصن لسه متفتحش،\nففي يوم قال رسول الله ﷺ :\n\" لأُعطِيَن الراية غداً رجلاً يُحب الله ورسوله ويحبه الله ورسوله، يفتح الله عليه\"\n☆ واضح جداً من الوصف إللي قاله رسول الله ﷺ إن مَن يفتح الله عز وجل على يديه البلاد، ويُمَكّن له في الأرض وينصره على أعدائه هو الشخص المحب لله ورسوله،\nوالصفة دي الإنسان مش هيكتسبها إلا بموافقة تاااامة للشرع وبصدق كامل في النية، وربنا مطلع على القلوب ولا يعطي نصره إلا لمن أحبه\nودي حاجة مش خاصة بحد معين، يعني أي قائد هيتوفر فيه الصفة دي ربنا هينصره ويمكّن له، \nوعلى مر تاريخ المسلمين كل الأبطال إللي ربنا فتح على إيديهم البلاد ومكن لهم في الأرض كانوا يحبون الله وموافقين موافقة تامة للشرع، فكان ربنا بينصرهم وده دليل على حبه لهم \nلما رسول الله ﷺ قال الكلام ده، كل واحد من الصحابة بقى يتمنى إنه يكون هو حامل الراية؛ لأن دي شهادة من رسول الله ﷺ بحب الله ورسوله للشخص ده وكمان حبه هو لله ورسوله،\nحتى إن عمر بن الخطاب رضي الله عنه قال :\n\"ما أحببت الإمارة أو ما تشرفت للإمارة إلا يومئذ\"\nيعني المرة الوحيدة إللي تمنيت فيها الإمارة كانت في اليوم ده،\nفلما أصبح الناس كانوا كلهم مستنيين مين إللي هياخد الراية، فسأل رسول الله ﷺ عن علي بن أبي طالب رضي الله عنه،\nفقيل له :\n\"هو يشتكي عينيه\" يعني عينه بتوجعه\nفأرسلوا إليه فأُتيَ به يُقاد، \nيعني عينه كان فيها رمد ومكنش شايف حاجة فحد مسكه من إيده يقوده لحد ما وصل عند رسول الله ﷺ،\nفلما رآه رسول الله ﷺ وعينه فيها الرمد، بصق في عينيه يعني تَفَل في عينيه ودعا له فبَرِأ من مرضه كأن لم يكن به وجع، يعني كأن عينه مكنش فيها أي مرض وعينه بقت صحيحة، وده من معجزات رسول الله ﷺ.\n☆طبعا السؤال إللي هييجي في بالنا دلوقتي هو:\nهل معنى إن رسول الله ﷺ قال إنه هيعطي الراية لرجل معين يحب الله ورسوله ويحبه الله ورسوله إن باقي الصحابة لا يحبون الله ورسوله ولا يحبهم الله ورسوله،\nوخصوصا إن في الصحابة من هو أفضل من علي رضي الله عنه وهم أبو بكر وعمر وعثمان رضي الله عنهم أجمعين\nطبعا لأ، لما رسول الله ﷺ قال كده كان المقصود من الكلام زيادة تخصيص للصفة دي، أو شهادة له رضي الله عنه بحبه لله ورسوله وحب الله ورسوله له من باب التكريم في الوقت ده،\nزي ما قلنا قبل كده إن رسول الله ﷺ قال عن أبو عبيدة عامر بن الجراح إن هو أمين هذه الأمة، \nهل معنى كده إن باقي الأمة مفيش فيها أمانة، لأ، ولكن زيادة تخصيص وتكريم للصفة دي عند أبي عبيدة رضي الله عنه\nتوجه علي بن أبي طالب رضي الله عنه لحصن الناعم بعد ما رسول الله ﷺ وصّاه ببعض الوصايا،\nإيه هي الوصايا دي، ويا ترى إيه هي نهاية مرحب، ده إللي ٠هنعرفه الجزء الجاي إن شاء الله"}, {"n": 163, "l": "الجزء 137 | احداث السنه السابعه من الهجرة | فتح خيبر الجزء الثالث | فتح حصن الناعم والصعب | تحريم الحمر الأهليه", "u": "https://www.facebook.com/groups/710210019782034/permalink/836490177154017/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#فتح_خيبر_الجزء_الثالث\n#فتح_حصن_ناعم_والصعب\n#تحريم_الحُمُر_الأهلية\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما أعطى راية جيش المسلمين لعلي بن أبي طالب رضي الله عنه وأمره إنه يتوجه لقتال اليهود في حصن الناعم،\nرسول الله ﷺ أوصى علي رضي الله عنه وقال له:\n\" انفُذ على رِسْلِك حتى تنزل بساحتهم، ثم ادعهم إلى الإسلام، وأخبرهم بما يجب عليهم من حق الله تعالى فيه، \nفوالله لَأَنْ يهدي الله بك رجلا واحدا خير لك من حُمْرِ النّعم\"\nيعني رسول الله ﷺ بيقول لعلي امشي على مهلك لحد ما تقرب منهم عشان يحسوا بالضعف والمؤمنين إللي معاك يتشجعوا لأنهم قربوا من عدوهم،\nلما تقرب منهم بقى ادعوهم إلى الإسلام، \nوبيّن رسول الله ﷺ إن إسلام هؤلاء اليهود إللي حزبوا الأحزاب ضد المسلمين وآذوا المسلمين وآذوا رسول الله ﷺ أحب إليه من أموالهم وديارهم،\nفالقضية بين رسول الله ﷺ وبين اليهود مش قضية شخصية ولا هي قضية انتقام،\nرسول الله ﷺ حريص إنه ينقذ الناس من النار حتى لو كانوا اليهود نفسهم ، فمع إن رسول الله ﷺ دعاهم كتير قبل كده لكن برده في اللحظة دي حريص على دعوتهم مرة أخيرة للإسلام لعلهم يهتدون،\n☆وكلام رسول الله ﷺ مش خاص بعلي بن أبي فقط،\n دي وصية عامة للجميع: \n\"لَأَنْ يهدي الله بك رجلا واحدا خير لك من حُمْرِ النّعم\" \nوحُمْر النعم هي الإبل الحُمُر المعروفة عند العرب، ويعظمونها، ويرونها أشرف الإبل،\nفالمقصود إن ربنا يهدي بك إنسان أحسن لك من الدنيا وما فيها\nوده يعرفنا قيمة وفضل الدعوة إلى الله، ويعرفنا إن القتال مش هو الغاية، الغاية هي هداية الناس وإخراجهم من الظلمات إلى النور،\nلكن ييجي القتال لما الناس يصروا على الكفر والشرك ويعاندوا ويصمموا على محاربة المسلمين ودينهم،\nوده عشان :\n◇يُستراح منهم وميصدوش باقي الناس عن سبيل الله.\n◇ميكونوش عقبة أمام المسلمين في طريق الدعوة إلى الله.\n◇يُستعان بأموالهم ونسائهم وذرياتهم على دين الله وطاعته\nوهنا مينفعش نقول إنه لا إكراه في الدين\nلأن الحرب هنا بين رسول الله ﷺ وبين اليهود مش عقاب لهم على ترك الإسلام أو رفضهم الدعوة،\nلكن رسول الله ﷺ بيعاقبهم على تجميعهم للأحزاب وتعريض المسلمين للإبادة،\nبيعاقبهم على تجسيهم على المسلمين في المدينة، \nبيعاقبهم على محاولاتهم لاغتيال رسول الله ﷺ وعلى تحفيزهم لقبائل غطفان أكثر من مرة لحرب المسلمين،\nلكن رسول الله ﷺ أعطى لهم فرصة أخيرة ليرفعوا عن أنفسهم العقاب وقال لهم لو أسلمتم خلاص هننسى كل إللي فات وتكونوا من المسلمين لكم ما لهم وعليكم ما عليهم،\nوموقف رسول الله ﷺ ده بيعلمنا سعة الصدر والرحمة حتى في وقت القتال\nلكن بعد كل ده اليهود رفضوا دعوة علي بن أبي طالب رضي الله عنه لهم بالإسلام، وقرروا الحرب، واغتروا بقوتهم وأعدادهم وحصونهم\nكان من عادة الحروب القديمة إنهم يبدأوا القتال بمبارزة بين واحد من الفرسان من فريق وواحد من الفرسان من الفريق الثاني، والمنتصر في المبارزة بيُعطي دَفْعة معنوية كبيرة جدا لفريقه، لأنه أظهر انتصار من أول المعركة،\nخرج من الحصن فارس من فرسان اليهود الأقوياء وكان زعيم حصن الناعم وهو مَرحب، إللي قلنا عنه المرة إللي فاتت إنه قتل الصحابي محمود بن مسلمة،\nمرحب ده كان قوي وكان عملاق ضخم الجثة، لما خرج مرحب خرج وهو بيقول مفتخر بنفسه:\nقد علمت خيبر أني مرحب ** شاكِي السلاح بطل مُجَرّب\nيعني أهل خيبر كلهم عارفيني وعارفين قوتي وعارفين شجاعتي وقهري للفرسان،\nوشاكي السلاح معناها تام السلاح،\nبعد ما قال الأبيات دي طلب المبارزة مع المسلمين فقال رسول الله ﷺ: مين يخرج له؟\nفقام الصحابي عامر بن الأكوع عشان يبارزه، وهو يقول:\nقد عَلِمَتْ خَيْبَرُ أَنِّى عَامِرُ** شَاكِى السِّلاَحِ بَطَلٌ مُغَامِرُ\nوبدأت المبارزة بينهم، وضرب عامر بن الأكوع مرحب اليهودي ضربة قوية بالسيف ، لكن الضربة دي طاشت وموصلتش لمرحب لكنها ارتدت على عامر وسقط السيف من إيده على ركبته فقتل عامر نفسه بسيفه خطأ\nفتأثر الناس باللي حصل لعامر وقالوا:\nقتل نفسه \nوحتى بعض الصحابة قالوا :ده حبط عمله \nلكن رسول الله ﷺ رد عليهم ومدح عامر بن الأكوع وقال:\nٌإن له لأجرين\n، وجمع بين إصبعيه ﷺ ، ثم قال: \n\"إنه لجاهد مجاهد قلّ عربي مشى بها مثله\"\nيعني هو مجتهد جداً في العلم والعبادة والعمل، وكمان مجاهد في سبيل الله، نادر جداً إن يكون في العرب حد زيه مشى في أرض المعركة أو مشى في الأرض بصفة عامة\nطبعا مقتل عامر بن الأكوع حصل بسببه هزة شديدة في معنويات المسلمين، في حين إنه رفع الروح المعنوية عند اليهود، \nفوقف قائد اليهود مرحب يطلب المبارزة مرة ثانية وهو يقول بيقول بفخر :\nقد علمت خيبر أني مرحب ** شاكِي السلاح بطل مُجَرّب\nفخرج له حامل راية المسلمين علي بن أبي طالب، وحصل  بينهما قتال شديد عنيف انتهى بانتصار علي بن أبي طالب رضي الله عنه وقَتْل مرحب،\nوقتل مرحب فيه إشارة كبيرة وواضحة إلى أن النصر هيكون من نصيب المسلمين\nليه\nلأن مرحب كان أقوى رجل في اليهود، ومحدش من اليهود كان يتصور أبدا أن يقتله أي واحد من المسلمين،\nفمقتل مرحب كان صدمة كبيرة جدا لليهود وزعزع من معنوياتهم،\nخرج أخو مرحب يطلب المبارزة عايز يثأر لمقتل أخيه وكان اسمه ياسر وكان هو كمان من العمالقة اليهود زي أخوه، \nفخرج لياسر أخو مرحب: \nالزبير بن العوام رضي الله عنه ، وحصل بينهم قتال واستطاع الزبير رضي الله عنه إنه يقتل ياسر أخو مرحب \nوكانت دي بداية الانتصار للمسلمين واشتد القتال بين الفريقين، \nولما حس اليهود بالهزيمة وشافوا شدة قتال المسلمين انسحبوا وهربوا من حصن ناعم وتركوه فارغ  للمسلمين، وتسللوا في الليل للحصن الثاني حصن: \n《الصّعب بن معاذ》\nوأخذ المسلمون حصن ناعم وما فيه من غنائم، لكن الغنائم  والمؤونة في الحصن ده كانت قليلة\nرسول الله ﷺ لم يكتفِ بالانتصار الجزئي في فتح حصن ناعم،\n هو عايز يُخرج اليهود من حول المدينة ويقضي على بؤرة الفساد دي إللي كل شوية تطلع مشاكل للمسلمين،\nفانتقل رسول الله ﷺ مع جيش المسلمين لحصار حصن الصعب بن معاذ،\nوحصن الصعب بن معاذ ده كان أشد صعوبة من الحصن إللي قبله حصن ناعم،\nمع إن وضع الحرب والحصار صعب إلا أن الله عز وجل أراد إنه يبتلي المسلمين بابتلاء أشد، وهو ابتلاء الجوع، \nجاع الصحابة جوع شديد، حتى إنهم قالوا:\n\"لقد جَهِدنا وما بأيْدِينا من شَيء\"\nيعني احنا تعبنا وجُعنا ومش معانا اي حاجة نتقوى بها،\nواستمر الحال كم يوم، \nولما زاد الجوع بالمسلمين قام بعض رجال الجيش الإسلامي بذبح بعض الحَمِير عشان يأكلوها،\nوالعرب بصفة عامة كانوا بياكلوا لحم الحمير في ظروف معينة فقط، ومكنش في أي حاجة في الدين ساعتها بتحرم أكل الحمير،\nفقاموا نصبوا القدور على النار ووضعوا اللحم فيها عشان يستوي، وكل ده ورسول الله ﷺ ميعرفش،\nفلما رسول الله ﷺ شاف النيران مشتعلة وعليها القدور سأل  الصحابة باستغراب:\n\" على أي شيء توقدون؟\"\nيعني انتم قايدين النار دي على إيه، إيه إللي موجود في القدور دي،\nلأنه ﷺ عارف إن مفيش في الجيش لحم عشان يسوُّوه،\nفقالوا: يا رسول الله! على لحم\nيعني احنا مولعين النار دي على لحوم،\nفقال لهم: أي لحم؟\n قالوا: \"لحوم الحُمُر الإنسية\" يعني: لحوم الحمير إللي نعرفها وبنستخدمها في النقل،\nفي الموقف الصعب ده، بعد ما الصحابة تعبوا في الذبح والسلخ والتنظيف والتقطيع وتوليع النار وكلهم مستنيين خلاص الأكل قرب يستوي وهم جعانين قال لهم رسول الله ﷺ:\n\"إن الله ورسوله ينهَيانِكم عن لحومِ الحُمُر الأهلية؛ فإنها رجس\"\nالموقف صعب بكل المقاييس، والاختبار شديد جدا، مش هينجح فيه غير المؤمن كامل الإيمان،\nوإلا ففي ناس بتسقط بسبب ابتلاءات أقل من كده بكتير،\n لكن بفضل الله نجح جيش الصحابة كلهم بلا استثناء في الاختبار العصيب ده ومحدش أكل من اللحوم دي،\nومحدش قال طيب ما كنت تقول من الأول يارسول الله ده احنا تعبنا على ما طبخنا\n أو مثلا محدش قال :خلاص هي المرة دي بس واحنا جعانين وفي حرب وممكن 《نتوب》 بعدين\nمفيش الكلام ده خالص كلهم 《سمعنا وأطعنا》، وده من أهم أسباب نصر الجيش المسلم: الطاعة المُطلقة الكاملة لله ورسوله\nلو في ولو معصية واحدة لله ورسوله مش هيبقى في نصر، وطبعا انتم أكيد مش ناسيين إللي حصل للصحابة في غزوة أحد\nومش بس رسول الله ﷺ نهاهم عن أكل اللحوم دي، ده قال لهم :\n\"أَرِيقُوها واكسروها\"\nيعني كُبُّوا كل اللحم إللي في القدور واكسروا القدور، عشان يختفي كل أثر للحوم دي،\nفتخيلوا بإيدهم بيرموا كل التعب إللي تعبوه طول اليوم،\nومع ذلك محدش فيهم اعترض،\nبس بعض الصحابة سألوا رسول الله ﷺ:\nأنريقها ونغسلها؟\nيعني بدل الكسر نغسل القدور، ونستفيد بيها في حاجة تانية، فقال لهم رسول الله ﷺ \nأو ذاك\nيعني رسول الله ﷺ رضي بغسل القدور بدل كسرها.\n☆ممكن حد يسأل ويقول، طيب مش الواحد لما يكون جعان ومش لاقي أكل ومضطر يجوز إنه يأكل الميتة، طيب لحم الحمير أخف من الميتة فليه رسول الله ﷺ لم يسمح للصحابة إنهم يأكلوا منه\nرسول الله ﷺ كان شايف إن موقف الصحابة لسه موصلش لموقف الاضطرار وإنهم وصلوا لمرحلة الهلاك ،\nهم لسه عندهم قوة إنهم يبقوا بدون طعام فترة من الزمان،\nفمكنش في اضطرار في الموقف ده\n☆ملحوظة سريعة\nسبب تحريم أكل لحم الحمير إن الحُمُر الأهلية دي : \n نجسة  - و خبيثة  - وتَأْكُلُ الْعَذِرَة يعني تأكل النجاسات والحاجات الخبيثة.\n◇في نقطة مهمة بقى عايزين نعرفها كويس وهي :\n\"إن ما حرم رسول الله ﷺ مثل ما حرم الله\"\nبمعنى إن تحريم الحُمر الأهلية مجاش في القرآن ولكنه جاء في السنة على لسان رسول الله ﷺ في حديث شريف،\nربنا في القرآن ذكر محرمات كثيرة على المسلمين، ولم يذكر منها الحُمُر الأهلية،\nفمش كل شرائع الإسلام موجودة في القرآن، السنة النبوية مكملة للقرآن، رسول الله ﷺ قال:\n\" ألا إني أُوتيتُ القرآن ومثله معه\"\nليه بقى بنقول الكلام ده\nلأن في ناس بتنكر السنة وأحاديث رسول الله ﷺ ، وبعد غزوة خيبر لما رسول الله ﷺ رجع للمدينة واحد من المنافقين قال إنه بيكتفي بالقرآن فقط ومش مقتنع بتحريم أكل الحمر الأهلية؛لأنه مش موجود في القرآن،\nفرسول الله ﷺ خطب في الناس وقال  عن المنافق ده وأمثاله إللي هييجوا بعدين في المستقبل:\nألا يُوشك رجل شبعان على أريكته يقول: \nعليكم بهذا القرآن فما وجدتم فيه من حلال فأحلُّوه، وما وجدتم فيه من حرام فحرّموه، ألا لا يَحِل لكم لحم الحمار الأهلي، ولا كل ذي نابٍ من السّباع\"\nيعني هييجي واحد وهو قاعد متكئ كده على سريره ولّا على الكنبة بتاعته وهو مالي بطنه وشبعان أكل وده يدل على التنعم إللي هو فيه، فيقول احنا هنشوف الحرام إللي في القرآن بس ونحرمه وملناش دعوة بحاجة غيره، \nوهو بيقول الكلام ده بسبب جهله ومن غير حتى ما يتعب نفسه في تحصيل العلم\nوالناس دي موجودة فعلا دلوقتي وهم والله جهلة\nده أصلا لو حد فيهم قرأ القرآن وعنده ذرة عقل وفِهم مكنش قال الكلام ده،\nيعني ربنا بيقول في القرآن:\n\"وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا\"\nودي آية واحدة بس من ضمن آيات كتيرة بتقول باتباع سنة رسول الله ﷺ\nفالخلاصة من الكلام إن القرآن والسنة مُكملين لبعض، من غير واحد فيهم التاني مش هيتفهم،\nوالسنة هي المصدر الثاني للتشريع في دين الإسلام\nوانتم شوفتم بنفسكم إزاي سيرة وسنة رسول الله ﷺ بتشرح آيات القرآن\nنرجع بقى للصحابة إللي واقعين في ابتلاء شديد دلوقتي ومش ظاهر حل\nالحصار شديد والحصن أقوى من إللي قبله ومش عارفين يفتحوه،\nفهنا لجأ المسلمون لجوءاً كاملاً إلى الله عز وجل\nفعند الأزمات يلجأ المسلم الصادق إلى الله عز وجل ليفرج عنه كربه وابتلاءه ويفتح له ابواب الرحمة\nوقف رسول الله ﷺ يدعو والصحابة يُأَمّنُون، قال ﷺ:\n اللهم! إنك قد عرفت حالهم، وأن ليست بهم قوة، وأن ليس بيدي شيء أُعطيهم إياه، فافتح عليهم أعظم حصونها عنهم غناء، وأكثرها طعاماً وودْكاً\n☆والوَدك هو : هو اللحم الدسم السمين.\nتاني يوم على طول فتح الله على المسلمين حصن الصعب بن معاذ، وكان من أغنى حصون خيبر بالطعام والشراب، \nوفيه ما لذ وطاب من ألوان الطعام المختلفة، ووجدوا فيه الطعام والودك زي ما دعا رسول الله ﷺ، وأكل الناس وشبعوا، ومن ترك شيئا لله عوضه الله خيراً منه\nانتقل المسلمون بعد كده للحصن الثالث وكان اسمه قلعة الزبير، حصل فيه إيه وإزاي المسلمون فتحوه، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 164, "l": "الجزء 138 | احداث السنه السابعه من الهجرة | فتح خيبر الجزء الرابع | فتح حصون منطقة النطاة والشق", "u": "https://www.facebook.com/groups/710210019782034/permalink/836503203819381/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#فتح_خيبر_الجزء_الرابع\n#فتح_حصون_منطقة_النّطاة_والشّق\nاتكلمنا المرة إللي فاتت عن فتح حصن ناعم وقلنا إنه تم فتحه على يد علي بن أبي طالب رضي الله عنه بعد قتاله مع  اليهود،\nوقلنا إن اليهود تسللّوا وهربوا من حصن الناعم في الليل وانتقلوا لحصن الصعب بن معاذ،\nوبرده تم فتح حصن الصعب بن معاذ بعد ما المسلمين حاصروه ثلاثة أيام،\nوكان اليهود بيُخرجُوا كتيبة عسكرية تقاتل المسلمين، ولو حسّوا بالهزيمة ينسحبوا للحصن ويقفلوا عليهم باب الحصن،\nفأخرج اليهود كتيبة من حصن الصعب بن معاذ عشان تقاتل المسلمين،\n☆ملحوظة \nالكتيبة العسكرية معناها:\nمجموعة من الجنود متقسمين لأربعة أو ست سرايا، عدد المجموعة العسكرية دي بيكون من ثلاثمائة إلى ألف جندي.\nهجم المسلمون بقيادة الصحابي الحُباب بن المنذر على كتيبة اليهود إللي خرجت وكان الحُباب هو حامل راية المسلمين في المرحلة دي،\nواستطاع إنه يهزم كتيبة اليهود ويسيطر على الباب ويمنع اليهود من إنهم يقفلوه،\nفلما شاف اليهود إن المسلمين دخلوا الحصن وخلاص بقى الحصن تحت سيطرتهم هربوا لحصن قلعة الزّبير وتم فتح حصن الصعب بن معاذ وأُسر بعض اليهود منهم سلاّم بن مُشكم الزوج السابق لصفية بنت حيي بن أخطب، وحيي هو زعيم اليهود إللي كان جمع الأحزاب وقُتل مع بني قريظة لو تفتكروا\nفقتل المسلمون سلاّم بن مُشكم؛ لأنه كان من أشد أعداء الإسلام ومن الناس إللي حركت الأحزاب لقتال رسول الله ﷺ،\nكان حصن الصعب بن معاذ أكثر حصن فيه طعام وشراب زي ما قلنا وكان فتح حصن الصعب بن معاذ استجابة لدعاء رسول الله ﷺ، \nومش بس الصحابة أخذوا الطعام والشراب إللي في الحصن، لكنهم لقوا أدوات حربية وأخذوها عشان يستعملوها في حربهم ضد اليهود،\nمن الأدوات الحربية كانت آلة لقذف الحجارة واسمها:\n《المَنْجَنِيق》  \nيبقى حصن الناعم وحصن الصعب بن معاذ اتفتحوا بعد قتال بين الفريقين\nووزّع رسول الله ﷺ الغنائم على الصحابة،\nوكان من الناس إللي رسول الله ﷺ أمر إنه يُعطى من الغنائم \nواحد من الأعراب أسلم لما كان جيش الصحابة مُتجه ناحية خيبر، فلما أسلم مشي مع جيش رسول الله ﷺ للجهاد،\nفلما أعطاه الصحابة نصيبه من الأغنام راح لرسول الله ﷺ وسأله:\nما هذا يارسول الله؟\nيعني انت بتديني من الغنائم دي ليه يارسول الله، وخصوصا إن الأعرابي ده كان بيرعى أمتعة الصحابة والأحصنة بتاعتهم يعني كان في آخر الجيش،\nفرسول الله ﷺ قال له إن ده نصيبه من الغنائم، والغنائم بتتوزع على الجيش كله وهو من الجيش،\nفالأعرابي قال لرسول الله ﷺ كلمة عجيبة\nقال :\n\"ما على هذا اتَّبعتُكَ ، ولَكِنِّي اتَّبعتُكَ على أن أُرمَى هاهُنا  بسَهْمٍ -وأشارَ إلى حلقِهِ - فأموتَ وأدخلَ الجنَّةَ\"\nيعني بيقول لرسول الله ﷺ يا رسول الله أنا مش جاي وراك ولا مُتبعك عشان تديني حاجة من الدنيا، \nأنا عايز أنضرب بسهم في حلقي وأموت شهيد وادخل الجنة، هو ده هدفي،\nرسول الله ﷺ رد عليه برد أعجب منه، ورد رسول الله ﷺ مش للأعرابي بس ده لكل واحد نفسه يدخل الجنة، قال رسول الله ﷺ:\n《 إن تَصدُقِ اللَّهَ يَصدُقْكَ》\nيعني لو انت فعلا صادق واتبعتني عشان همك الشهادة والآخرة والجنة ربنا هيرزقك الشهادة وتدخل الجنة\nيعني يا جماعة إللي بيقول أنا نفسي ربنا يهديني لو هو صادق فعلا ونفسه ربنا يهديه الهداية الصحيحة مش إللي على مزاجه، ربنا هيهديه وهييسر له طريق الهداية ويعينه عليه،\nوخدوا بالكم من إن في ناس كتير نفسها ربنا يهديها بس هداية على مزاجها\nيعني تبقى عايزة تصلي وتصوم وتقول الأذكار وكده حلو قوي، لكن نيجي نقول ده عمل الحواجب حرام، تقول لأ، حرام إيه الكلام ده مش صح،\nنقول الأغاني والموسيقى والأفلام والمسلسلات حرام تقول ده الموسيقى غذاء الروح ومادام مش بتحرك المشاعر خلاص،\nومالها الأفلام والمسلسلات دي مفيدة وبتعالج مشاكل المجتمع\nفالصادق بقى هيبقى عايز الهداية إللي ربنا يُريدها، على منهج رسول الله ﷺ فربنا هيرزقه فعلا الهداية بغض النظر عن الطريقة عاملة إزاي،\nيعني الأعرابي ده كلامه عجيب وبالعقل أصلا مستحيل يجيله سهم يقتله؛ لأن هو في آخر الجيش مهمته إنه يرعى  الأمتعة وملوش دعوة بالقتال أصلا،\nفالبعقل عشان يموت شهيد لازم يكون في الصفوف الأمامية من باب الأخذ بالأسباب حتى\nلكن المفاجئة إللي حصلت إن الأعرابي ده جاله سهم وهو في آخر الجيش في نفس المكان إللي أشار له بالضبط ومات\nوجاء به الصحابة لرسول الله ﷺ وهم شايلينه فقال رسول الله ﷺ وهو متعجب:\n أَهوَ هوَ ؟!!!\nيعني هو نفس الرجل إللي لسه قايلي الكلام ده،\nفقال الصحابة: نعَم \nفقالَ رسول الله ﷺ : 《صدقَ اللَّهَ فصدقَهُ》\nيعني هو فعلا كان صادق مع ربنا فكانت النتيجة إن ربنا أعطاه إللي تمناه مع إن كل الأسباب كانت بتقول إن مستحيل الأعرابي ده يموت شهيد؛ لأنه بعيد أصلا عن الصفوف الأمامية للقتال،\nلكن مع ربنا مفيش مستحيل، الصدق بيخلي المستحيل واقع، وفي كلمة قرأتها من زمان بتقول:\n《اصْدق مع الله ولو مرة وسَترى العَجَب》\nربنا يرزقنا وإياكم الصدق والإخلاص في القول والعمل\nنرجع بقى للمعركة،\nهرب اليهود وراحوا لحصن قلعة الزبير، وهو الحصن الثالث في منطقة النّطَاة،\nوكانت الحصون مبنية بمهارة عجيبة، بحيث إن كل حصن متصل بالحصن التاني\nحصن قلعة الزبير كان من أمنع الحصون وأشدها في هذه المنطقة، والرُّواة كانوا بيقولوا عنه:\nلا تقدر عليه الخيل والرجال\nلأن الحصن ده كان فوق قمة جبل، وكان صعب الوصول إليه، ففرض رسول الله ﷺ الحصار على حصن قلعة الزبير لمدة ثلاثة أيام لكن مفيش أي تقدم\nسبحان الله، ربنا ألقى الرعب في قلب رجل من اليهود، \nفتسلل من الحصن، وجاء إلى رسول الله ﷺ وطلب الأمان، وبعدين قال لرسول الله ﷺ :\nيا أبا القاسم! \nإنك لو أقمت شهراً ما بالوا، إنّ لهم شراباً وعُيوناً تحت الأرض، يخرجون بالليل ويشربون منها ثم يَرجعون إلى قلعتهم فيمتنعون منك، فإن قطعت مَشْربهم عليهم أصحروا لك\"\nيعني بيقول لرسول الله ﷺ ده انت لو قعدت مُحاصر الحصن لمدة شهر، اليهود ولا يهتموا،\nده عندهم عيون ماء تحت الأرض تدخل للحصن، وهم في كل ليلة بيخرجوا من غير ما المسلمون يحسوا بيهم ويأخذوا  من الماء ويتحصنوا في الحصن،\nفلو انت قطعت عليهم الماء هيستسلموا لك لأنهم مش هيقدروا يعيشوا من غير الماء،\nفقطع رسول الله ﷺ والصحابة الماء عن اليهود، فخرج اليهود من الحصن وقاتلوا قتال شديد جدا، واستمر القتال بين اليهود وبين جيش المسلمين لحد ما انتصر المسلمون، وتم فتح قلعة الزبير\nوما يعلم جنود ربك إلا هو\nاليهودي إللي دل رسول الله ﷺ على سر الماء كان سبب في فتح الحصن،\nفجاء النصر من طريق محدش كان يتوقعه أبدا،\nوده يعلمنا إن احنا فقط علينا بذل الأسباب أما النصر فييجي من عند الله بالطريقة إللي ربنا يُريدها، ومش لازم زي ماحنا كنا متوقعين\nوبكده يبقى تم فتح كل حصون خيبر في منطقة النّطاة\n☆طبعا الكلام والحكاية غير الوضع على أرض الواقع\nيعني فتح الحصون مكنش سهل، ده كل حصن أخذ له أيام من الحصار والمحاولات الصعبة لفتحه،\nوهجوم ودفاع وقتال وناس تسقط جرحى وناس تسقط قتلى، وناس تسهر للحراسة،\nفالموضوع مكنش سهل خالص، وليس الخبر كالمُعَايَنَة\nيعني إللي عاش الموقف زي الصحابة ما عاشوا الحصار والقتال غير إللي سمع عنه زيّنا كده\nاليهود استطاعوا انهم يهربوا لمنطقة الشّق إللي كان فيها الحصن الرابع والخامس من حصون اليهود الرئيسية وهما حصن قلعة أُبَي، وحصن النّزَار،\nحصل قتال عنيف حول قلعة أُبي وكان حامل الراية في الهجوم على حصن أُبي هو أبو دُجانة رضي الله عنه، واستمر الحصار والقتال لحد ما تم فتح الحصن وهرب اليهود تاني للحصن إللي وراه وهو حصن النّزَار،\nحصن النزار ده بقى كان أمنع حصون اليهود على الإطلاق، عشان كده وضعوا في الحصن ده الأطفال والنساء،\nعلى أساس إن محدش هيقدر يقتحم الحصن ده،\nوفعلا قعد رسول الله ﷺ محاصر لحصن النزار أيام طويلة لو قارنّاه بالحصون إللي فاتت،\nواليهود مش راضيين يخرجوا من الحصن سواء للقتال أو المبارزة، خايفين طبعا على نساءهم وأطفالهم،\nوكل ما المسلمين يحاولوا يقربوا من الحصن اليهود يرموهم بالسهام فميقدروش يقربوا،\nيُقال إن رسول الله ﷺ قعد أربعة عشرة يوما أو عشرين يوم محاصر لحصن النزار ومفيش أي مؤشرات ولا دلائل إن الحصن ده هيتفتح\nفلجأ رسول الله ﷺ لطريقة جديدة في الحرب مستعملهاش قبل كده، والحكمة ضالة المؤمن أنّى وجدها فهو أَوْلَى الناس بها\nيعني لو في أي حاجة هتفيد المسلم سواء في دينه أو دنياه يبقى يستعملها مادامت لا تخالف شرع الله،\nالطريقة إللي رسول الله ﷺ استعملها هي :\n《المَنْجَنِيق》آلة قذف الحجارة،\nجاءوا بالمنجنيق وبدأوا يقصفوا جدار الحصن، وأمرهم رسول الله ﷺ إنهم يركزوا القصف على منطقة معينة بحيث إنهم يُضعفوا المنطقة دي ويقدروا يتسللوا منها لداخل الحصن،\nوفعلا أحدث المسلمون خلل في بعض جدران الحصن واستطاع المسلمون الدخول للحصن وحصل قتال شديد جدا  بين المسلمين واليهود يُعتبر من أعنف القتال إللي حصل بين الفريقين،\nوكتب الله عز وجل النصر للمسلمين، وتم فتح الحصن العظيم حصن النزار، وهرب منه بقية اليهود إلى حصون المنطقة الأخيرة إللي كان اسمها منطقة الكتيبة، وتركوا وراءهم النساء والأطفال وكل شيء\nوأخذ الصحابة النساء والأطفال سبايا، وأخذوا الغنائم من الأموال والثمار وغيرها،\nوكان من الحاجات إللي الصحابة غنموها من الحصون صحائف من التوراة،\nومع إن التوراة كانت مُحرّفة إلا إن رسول الله ﷺ تركها لليهود ولم يَحرقها زي ما الرومان كانوا بيحرقوا كتب التوراة لليهود لما كانوا بيهزموهم،\nولم يَحرقها زي ما النصارى حرقوا كتب المسلمين في الأندلس بعد ما هزموهم،\nالإسلام يرعى حقوق غير المسلمين حتى في الحروب\nكده وصلنا لآخر منطقة وهي منطقة الكَتِيبة وكان فيها آخر حصون اليهود الرئيسية،\nحصل فيها إيه وتم فتحها إزاي، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 165, "l": "الجزء 139 | احداث السنه السابعه من الهجرة | فتح خيبر الجزء الخامس والاخير | عودة جعفر", "u": "https://www.facebook.com/groups/710210019782034/permalink/836504203819281/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_وثلاثون\n#أحداث_السنة_السابعة_من_الهجرة\n#فتح_خيبر_الجزء_الخامس_والأخير\n#عودة_جعفر\nاتكلمنا المرة إللي فاتت عن فتح حصون منطقة الشّق، وانتقال رسول الله ﷺ والصحابة لفتح حصون منطقة الكتيبة إللي هرب إليها اليهود بعد هزيمتهم في حصن النّزار إللي كان فيه نساؤهم وأطفالهم،\nمنطقة الكتيبة كان فيها ثلاثة حصون:\nحصن القَمُوص، وحصن الوَطِيح، وحصن السّلاَلِم، مع إن الحصون دي كانت منيعة إلا إن اليهود كانوا مهزومين نفسيا بسبب هزيمتهم المتكررة أمام رسول الله ﷺ والصحابة،\nوخصوصا في آخر حصن إللي فقدوا فيه نساءوهم وأطفالهم،\nفمعركة خيبر مش مجرد قتال مدته ساعتين ثلاثة زي غزوة بدر مثلا وانتهى الموضوع ،\nدي كانت معركة وراء معركة والقتال استمر أيام لم يُهزم فيه المسلمون هزيمة واحدة \nواليهود لحد زماننا الحاضر فاكرين غزوة خيبر، ولما حرقوا المسجد الأقصى عام 1969 قال وزير دفاعهم مُوشى دَيان:\n\"هذا يومٌ بيومِ خيبر\"\nفمعركة خيبر محفورة في عقول اليهود فهي أكبر المعارك إللي حصلت بين اليهود والمسلمين وكانت من أعظم انتصارات المسلمين مُطلقا\nفاحنا وصلنا دلوقتي لآخر ثلاثة حصون، حاصر رسول الله ﷺ حصن القَموص أربعة عشرة يوماً،\nوالعلماء اختلفوا هل الحصن ده فُتح بعد قتال ولّا اليهود استسلموا بدون قتال\nفسواء حصل القتال ولّا لأ النتيجة كانت فتح الحصن، أما حصن الوَطِيح، وحصن السّلاَلِم فدول أكيد فُتحوا من غير قتال،\nيعني اليهود استسلموا لرسول الله ﷺ وطلبوا منه إنه يكون في بينهم وبينه صلح،\nوكان إللي عمل الصلح مع رسول الله ﷺ رئيسهم كِنانة بن الربيع بن أبي الحُقيق زوج صفية بنت حُيَي بن أخطب،\nوكمان كِنانة ده أخو أبو رافع سلّام بن أبي الحُقيق إللي قتله عبد الله بن عتيك واتكلمنا عنه قبل كده\nكنانة بن أبي الحقيق قعد مع رسول الله ﷺ عشان يفاوضه على الصلح، \nوبعد حوار طويل بينهم كان الاتفاق على حقن دماء كل إللي في الحصون من المقاتلين، يعني عدم قتلهم،\nوده في مقابل إن اليهود يتركوا أرض خيبر، ويتركوا الأموال والذهب والفضة وكل شيء،\nورسول الله ﷺ اشترط عليهم شرط، قال:\n\"وبَرِأت منكم ذمة الله وذمة رسوله إن كَتَمْتُمُوني شيئاً\"\nيعني لو حصل إن أي حد فيكم أخفى أموال عن المسلمين وخالف العهد؛ يبقى العهد مُنتهي ويُقتل إللي خالف الشرط،\nووافق اليهود على شرط رسول الله ﷺ وبدأوا يتجهزوا للخروج من خيبر،\nلكن اليهود فكّروا في عرض وعرضوه على رسول الله ﷺ قالوا له:\n\"يا محمد! \nدعنا نكون في هذه الأرض نُصْلحها ونقوم عليها، فنحن أعلم بها منكم\"\nيعني بيقولوا لرسول الله ﷺ إن أرض خيبر كبيرة جدا واحنا خبراء بالزراعة وأعلم بيها منكم، فخلينا احنا نزرعها لكم، فوافق رسول الله ﷺ على عرض اليهود وخصوصا إن الصحابة معندهمش علم كبير بالزراعة\nوكمان خيبر بعيدة عن المدينة ومحتاجين حد يهتم بالزراعة، فالعرض كان في مصلحة المسلمين من كل ناحية،\nفكان الاتفاق إن اليهود يفضلوا في خيبر يزرعوها للمسلمين في مقابل إنهم يقتسموا الثمار، \nيعني المحصول إللي هيطلع نصه للمسلمين ونصه لليهود مقابل شغلهم في الزراعة،\nلكن رسول الله ﷺ كان له شرط، قالهم إنه هيتركهم في خيبر، لكن في أي وقت رسول الله ﷺ عايز يخرجهم، يخرجهم،\nيعني لو رسول الله ﷺ شاف إنه في يوم من الأيام إنه مش عايز اليهود في أرض خيبر يبقى يجب عليهم إنهم يخرجوا من أرض خيبر بدون أي اعتراض\nوطبعا الفرق واضح جدا بين المعاهدات إللي رسول الله ﷺ عملها مع اليهود وبين المعاهدات إللي العرب بيعملوها مع اليهود في عصرنا دلوقتي\nرسول الله ﷺ له اليد العليا والمعاهدات كلها كانت في مصلحة المسلمين، بعكس المعاهدات في زماننا كلها ظلم وتنازلات لليهود،\nوطبعا ده رد واضح على إللي بيقول ماهو رسول الله ﷺ عمل معاهدات مع اليهود،\nأيوة عمل معاهدات معاهم لكن المصلحة في صالح المسلمين مش العكس\nوبكده انتهت معركة خيبر، وبدأ رسول الله ﷺ يقسم الغنائم على المسلمين، والغنائم من خيبر كانت كثيرة جدا زي ما ربنا قال:\n\"وَعَدَكُمُ اللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا\"\nحتى إن السيدة عائشة رضي الله عنها قالت:\n\"لما فُتحت خيبر قلنا: الآن نشبع من التمر\"\nواحنا عارفين إن الصحابة سواء المهاجرين أو الأنصار كانوا فقراء جدا،\nوشوفنا قبل غزوة خيبر بسنة أو أكثر تقريبا غزوة الأحزاب كانوا عاملين فيها إزاي وظهر شدة فقرهم،\nفكان فتح خيبر هو النقلة إللي نقلت الصحابة من شدة الفقر إللي كانوا فيها لوضع أفضل،\nطبعا مبقوش أغنياء لكن خرجوا من شدة الفقر وتحسن وضعهم أكثر من الأول\nكنانة بن أبي الحُقيق إللي وافق على شروط المعاهدة أخفى أموال عن رسول الله ﷺ، مع إن الشرط بيقول إن لو واحد من اليهود أخفى أموال عن رسول الله ﷺ يُقتل\nلما سأله رسول الله ﷺ عن الأموال إللي أخفاها أنكر وقال إنه مخباش حاجة،\nفقال له رسول الله ﷺ لو لقينا الأموال دي نقتلك؟\nفوافق كنانة\nولما الصحابة وجدوا الأموال إللي كان كنانة بن أبي الحقيق مخبيها في مكان مهجور قتله رسول الله ﷺ لمخالفته للعهد، وياريت الموضوع انتهى على كده\nمؤمرات اليهود ضد رسول الله ﷺ موقفتش، تخيلوا إنهم اجتمعوا على اغتيال رسول الله ﷺ \nامرأة من اليهود طبخت شاة، مِعزة يعني\nعشان تقدمها لرسول الله ﷺ وأصحابه كهدية، وسألت عن أي جزء رسول الله ﷺ بيحب ياكله من الشاة فقالوا لها لحم الكتف،\nفالمرأة اليهودية وضعت السم في الشاة وأكثرت من السم في لحم الكتف\nوالمرأة دي كانت زوجة سلّام بن مُشكم إللي قتله المسلمون وهم بيفتحوا الحصون إللي فاتت،\nقعد رسول الله ﷺ ومعاه بعض الصحابة عشان يأكلوا،\nرسول الله ﷺ أكل شيء يسير من الشاة، فكلمه ذراع الشاة وقال له إن الشاة مسمومة، ودي من معجزات رسول الله ﷺ،\nشاة مذبوحة ومشوية ربنا ينطقها لرسول الله ﷺ وتقول له إنها مسمومة\nفقال رسول الله ﷺ للصحابة إللي معاه محدش ياكل، الشاة دي قالت لي إنها مسمومة،\nلكن كان واحد من الصحابة أكل وبلع قطعة لحم من الشاة المسمومة دي والصحابي ده كان اسمه: \n《بِشْر بن البراء بن معرور》\n☆لو تفكتروا أبوه البراء بن معرور كان رئيس الوفد الإسلامي في بيعة العقبة الثانية ومات قبل هجرة رسول الله ﷺ بحوالي شهرين، فابنه بقى بِشر أكل من الشاة المسمومة دي\nرسول الله ﷺ قال للصحابة اجمعوا لي اليهود الموجودين هنا، فلما جاءه اليهود قال لهم رسول الله ﷺ:\n\" إِنِّى سَائِلُكُمْ عَنْ شَىْءٍ فَهَلْ أَنْتُمْ صَادِقِىَّ عَنْهُ\"\nيعني رسول الله ﷺ بيقول لهم أنا هسألكم عن حاجة، فهل هتقولوا الحقيقة ولّا هتكذبوا عليّ،\nفَقَالُوا : نَعَمْ، يعني هنقول الصدق،\nفقال لهم رسول الله ﷺ:\nمَنْ أَبُوكُمْ ؟ \nقَالُوا : فُلاَنٌ .\nفَقَالَ ﷺ: كَذَبْتُمْ ، بَلْ أَبُوكُمْ فُلاَنٌ.\nقَالُوا : صَدَقْتَ.\nيعني رسول الله ﷺ بيسألهم عن نسلهم ومين هو أبوهم، فكذبوا عليه وذكروا له اسم رجل معين،\nفرسول الله ﷺ كذبهم وقال لهم إن أبوهم الحقيقي فلان، فقالوا له صدقت، يعني انت صح واحنا كذبنا،\nوبالسؤال ده رسول الله ﷺ أثبت لهم إنه يقدر يكتشف الكذب إللي بيكذبوه عن طريق الوحي، \nفقال لهم:\n\"فَهَلْ أَنْتُمْ صَادِقِىَّ عَنْ شَىْءٍ إِنْ سَأَلْتُ عَنْهُ\"\nيعني بيقول لهم لو سألتكم عن حاجة تانية دلوقي هتقولوا الصدق ولاّ هتكذبوا عليّ،\nفَقَالُوا : \n\"نَعَمْ يَا أَبَا الْقَاسِمِ ، وَإِنْ كَذَبْنَا عَرَفْتَ كَذِبَنَا كَمَا عَرَفْتَهُ فِى أَبِينَا\"\nيعني بيقولوا هنقول الصدق ولو احنا كذبنا عليك هتعرف إننا كذبنا زي ما عرفت في موضوع أبونا،\nفَقَالَ لَهُمْ : مَنْ أَهْلُ النَّارِ؟\nفقالوا:\n\"نَكُونُ فِيهَا يَسِيرًا ثُمَّ تَخْلُفُونَا فِيهَا\"\nيعني رسول الله ﷺ بيسألهم مين أهل النار، فقالوا له احنا هندخلها نتعذب شوية وبعدين ربنا يطلعنا وانتم تدخلوا بدالنا تقعدوا فيها للأبد،\nفَقَالَ النَّبِىُّ ﷺ : \"اخْسَئُوا فِيهَا ، وَاللَّهِ لاَ نَخْلُفُكُمْ فِيهَا أَبَدًا\"\nيعني انتم أهلها ومش هتخرجوا منها واحنا مش هندخلها،\nثُمَّ قَالَ : \nهَلْ أَنْتُمْ صَادِقِىَّ عَنْ شَىْءٍ إِنْ سَأَلْتُكُمْ عَنْهُ ؟\nفَقَالُوا : نَعَمْ يَا أَبَا الْقَاسِمِ .\nقَالَ: هَلْ جَعَلْتُمْ فِى هَذِهِ الشَّاةِ سُمًّا؟\nسألهم بقى عن الشاة، هل وضعوا فيها سم ولّا لأ،\nفقَالُوا : نَعَمْ\nيعني اليهود اجتمعوا على إنهم يضعوا السم في الشاة عشان يقتلوا رسول الله ﷺ وبعدين أعطوا الشاة لزوجة سلّام بن مشكم لتهديها لرسول الله ﷺ،\nفسألهم رسول الله ﷺ:\nمَا حَمَلَكُمْ عَلَى ذَلِكَ؟\nيعني إيه إللي خلاكم تعملوا كده، قالوا:\n\"أَرَدْنَا إِنْ كُنْتَ كَاذِبًا نَسْتَرِيحُ ، وَإِنْ كُنْتَ نَبِيًّا لَمْ يَضُرَّكَ\"\nيعني لو انت كذاب ومش رسول ولا حاجة نقتلك ونرتاح منك، لكن لو انت فعلا رسول من عند الله السم مش هيضرك في حاجة\nفهم كده اعترفوا على نفسهم اعتراف صريح جازم بأنهم دبروا محاولة لقتله ﷺ، ومع ذلك عفى عنهم رسول الله ﷺ جميعا حتى عفا عن المرأة اليهودية،\nلكن الصحابي بشر بن البراء بن معرور مات بسبب قطعة اللحم المسمومة إللي أكلها، فأقام رسول الله ﷺ حد القتل على المرأة اليهودية لأنها قتلت مسلم،\nيعني رسول الله ﷺ وجيش المسلمين لم يقتلوا من 《المدنيين》 غير امرأة واحدة فقط، ولم يقتلوها ظلما وعدوانا ده قتلوها قصاصا لقتلها رجل مسلم\nوبعد كل ده ييجي واحد يقولك ده الإسلام ده دين الإرهاب والقتل\nالمهم، \nنصْر المسلمين في خيبر كان له أثار كبيرة في شبه الجزيرة العربية وخصوصا في المناطق المحيطة بخيبر،\nيعني مثلا منطقة فَدَك ومنطقة تَيْماء كان فيها يهود، فلما شافوا إللي حصل في خيبر قرروا إنهم يصالحوا رسول الله ﷺ بنفس الصلح إللي يهود خيبر صالحوا عليه رسول الله ﷺ،\nيهود وادي القُرى قاوموا شوية في البداية وبعدين عملوا هم كمان صلح مع رسول الله ﷺ،\nوبكده يبقى رسول الله ﷺ أخضع يهود الجزيرة العربية تحت حكم المسلمين عن طريق الصلح\nمع فتح خيبر حصل أمر جعل رسول الله ﷺ سعيد جدا؛ وهو  مجيء جعفر بن أبي طالب رضي الله عنه مع باقي الصحابة إللي كانوا معاه في الحبشة\nكنا قلنا إن عمرو بن أمية الضمري راح للنجاشي برسالة رسول الله ﷺ وخطب أم حبيبة لرسول الله ﷺ،\nوكلم النجاشي إنه يرسل معاه الصحابة للمدينة خلاص بعد ما استقرت الأوضاع،\nفتحرك آخر الصحابة إللي كانوا في الحبشة وعادوا إلى المدينة بقيادة جعفر بن أبي طالب رضي الله عنه وهو ابن عم رسول الله ﷺ،\nفالصحابة هاجروا من الحبشة للمدينة على دفعات، آخر المجموعات كانت مجموعة جعفر رضي الله عنه، وصل لرسول الله ﷺ مع فتح خيبر وكان أول لقاء بين رسول الله ﷺ وبين جعفر بن أبي طالب بعد فراق أكثر من ثلاثة عشرة سنة،\nفلما رآهم رسول الله ﷺ فرح بيهم جدا وقال:\n\"ما أدري بأيّهما أنا أُسَر: بفتح خيبر، أم بقدوم جعفر\"\nيعني أنا مش عارف أفرح بمين أكثر بفتح خيبر ولّا بقدوم جعفر، \nوقَسَم لهم رسول الله ﷺ من غنائم خيبر بعد ما استأذن من باقي الصحابة؛لأن الغنيمة تكون للي بيشارك في القتال \nوبما إننا بنتكلم عن عودة الصحابة من الحبشة؛ فخلونا نحكي عن قصة حصلت بين أسماء بنت عُمَيس زوجة جعفر بن أبي طالب وعمر بن الخطاب\nأسماء بنت عُميس راحت زارت حفصة بنت عمر بن الخطاب زوجة رسول الله ﷺ بعد ما رجعت من الحبشة،\nفدخل عمر رضي الله عنه على ابنته حفصة، فوجد عندها امرأة فسألها هي مين دي،\nفقالت له حفصة:\nأسماء بنت عُميس!\nفقال عمر: \n\"الحبشية هذه البحرية هذه\"\nيعني إللي هاجرت للحبشة وركبت البحر، \nفقالت أسماء: نعم.\nفقال عمر :\nسبقناكم بالهجرة فنحن أحق برسول الله ﷺ منكم \nفغضبت أسماء رضي الله عنها \nوقالت لعمر:\n كَذبْت يا عمر، كلا والله \nكنتم مع رسول الله ﷺ يُطعم جائعكم ويَعظ جاهلكم وكنا في أرض البُعداء البُغضاء في الحبشة وذلك في الله وفي رسوله،\nوايْم الله لا أطعم طعاما ولا أشرب شرابا حتى أذكر ما قلت لرسول الله ﷺ،\nونحن كنا نُؤذى ونخاف وسأذكر ذلك لرسول الله ﷺ وأسأله ووالله لا أكذب ولا أزيغ ولا أزيد على ذلك\nكلمة كَذَبت هنا يعني أَخْطأت مش معناها الكذب المعروف إللي هو عكس الصدق،\nفهي بتقول لعمر رضي الله عنه: \nانت غلطان ياعمر، رسول الله ﷺ كان معاكم لو حد فيكم جاع يُطعمه، لو حد فيكم عايز يتعلم حاجة بيعلمه لكن احنا كنا هناك لوحدنا في وسط ناس غريبة عننا وكفار، \nوكنا بنُؤذَى وبنخاف ومع ذلك كنا صابرين على كل إللي احنا فيه لله ورسوله، \nوالله ما هاكل ولا أشرب غير لما أروح لرسول الله ﷺ واسأله عن الكلام إللي انت قلته ده، ومتخفش مش هكذب ولا هزوّد في الكلام ولا هغيره،\nفلما راحت لرسول الله ﷺ قالت له :\nيا نبي الله إن عمر قال كذا وكذا \nفقال رسول الله ﷺ:\n\"ليس بأحق بي منكم، وله ولأصحابه هجرة واحدة ولكم أنتم أهل السفينة هجرتان\"\nيعني بيقولها إن كلام عمر مش صح، وانكم لكم فضل مش لحد وهو إنكم هاجرتم مرتين مرة للحبشة ومرة للمدينة بعكس باقي الصحابة إللي هاجروا مرة واحدة،\nفكان كلام رسول الله ﷺ لأسماء وأصحاب السفينة أغلى عندهم من أي شيء ولم يفرحوا بحاجة زي ما فرحوا بكلام رسول الله ﷺ،\n قالت أسماء بنت عميس رضي الله عنها:\n\"فلقد رأيت أبا موسى وأصحاب السفينة يأتوني أَرْسالا يسألوني عن هذا الحديث، ما من الدنيا شيء هُم به أَفرح ولا أعظم في أنفسهم مما قال لهم رسول الله ﷺ\"\n يعني أصحاب السفينة إللي هاجروا للحبشة كانوا بيأتوا لأسماء أفواج يسألوها عن الكلام إللي رسول الله ﷺ قال لها ومكنش عندهم حاجة أعظم في نفوسهم من بشارة رسول الله ﷺ\nلما قسم رسول الله ﷺ الغنائم، كانت من ضمن الغنائم السّبي من النساء والأطفال، ومن نساء السّبْي كانت صفية بنت حُيي بن أخطب زوجة كنانة بن أبي الحقيق إللي قتله رسول الله ﷺ،\nفكانت صفية من نصيب الصحابي دِحْية الكلبي، فواحد من الصحابة قال لرسول الله ﷺ إن صفية زوجة ملك وابنة ملك مينفعش تكون عند حد غيرك، فوافق رسول الله ﷺ إنه يأخذها.\nإيه إللي حصل بين رسول الله ﷺ وبين صفية بنت حيي بن أخطب، ده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
